window.__INLINE_SOURCES = {"astra/acceptance-patterns/pattern-1-simple-validation/src/main/astra/PatternRunner.astra": "// Pipeline: main > !classified(food) > !deliberated > accept|reject\n// Pattern 1: Simple Validation - ASTRA\n//\n// The simplest governance pattern: record acceptance for valid output, reject invalid output.\n// Demonstrates the fundamental decide() context-guard branching.\nagent PatternRunner {\n    module gl.astra.GL gl;\n    module Console console;\n    module System S;\n\n    types governance {\n        formula binding(string);\n        formula validated(string);\n        formula accepted(string);\n        formula rejected(string);\n        formula classified(string, string, string);\n    }\n\n    inference validated(string cid) :- accepted(cid);\n    inference validated(string cid) :- rejected(cid);\n\n    rule +!main(list args) {\n        !banner();\n        +binding(gl.bind(\"agent1\", \"groq\", \"openai/gpt-oss-120b\", \"\"));\n        !classified(\"apple\");\n        !shutdown();\n    }\n\n    // ACHIEVEMENT: clean exit\n    rule +!shutdown() {\n        S.exit();\n    }\n\n    // ACHIEVEMENT: display banner\n    rule +!banner() {\n        console.println(\"=== Pattern 1: Simple Validation ===\");\n        console.println(\"\");\n        console.println(\"[Layer] Available providers: \" + gl.see());\n    }\n\n    // DECOMPOSITION: classify = call + deliberate\n    rule +!classified(string foodItem) : binding(string bid) {\n        !deliberated(gl.call(bid, \"classify_food\", \"llm.answer\", \"ANSWER\",\n            \"Classify the food item '\" + foodItem + \"'. Return label and confidence.\",\n            \"label,confidence\", \"\"));\n    }\n\n    // SERENDIPITY: already deliberated\n    rule +!deliberated(string rid) : validated(gl.candidate(rid)) {\n        console.println(\"[AGENT] Already deliberated: \" + rid);\n    }\n\n    // DECOMPOSITION: admissible > accept + trace\n    rule +!deliberated(string rid) : gl.decide(gl.candidate(rid)) == \"ADMISSIBLE\" {\n        !accepted_candidate(rid, gl.candidate(rid));\n        !print_trace(rid);\n    }\n\n    // DECOMPOSITION: not admissible > reject + trace\n    rule +!deliberated(string rid) {\n        !rejected_candidate(gl.candidate(rid), rid);\n        !print_trace(rid);\n    }\n\n    // ACHIEVEMENT: accept (actions only)\n    rule +!accepted_candidate(string rid, string cid) {\n        console.println(\"\");\n        console.println(\"[AGENT] Candidate is ADMISSIBLE.\");\n        console.println(\"[AGENT]   label      = \" + gl.get(cid, \"label\"));\n        console.println(\"[AGENT]   confidence = \" + gl.get(cid, \"confidence\"));\n        gl.accept(cid, \"valid classification\");\n        +accepted(cid);\n        +classified(\"food\", gl.get(cid, \"label\"), gl.get(cid, \"confidence\"));\n        console.println(\"[AGENT] Candidate ACCEPTED. Domain belief added explicitly by the agent program.\");\n    }\n\n    // ACHIEVEMENT: reject (actions only)\n    rule +!rejected_candidate(string cid, string rid) {\n        gl.reject(cid, \"failed validation\");\n        +rejected(cid);\n        console.println(\"\");\n        console.println(\"[AGENT] Candidate REJECTED.\");\n        console.println(\"[AGENT]   reason = \" + gl.explain(rid));\n    }\n\n    // ACHIEVEMENT: print trace\n    rule +!print_trace(string rid) {\n        console.println(\"\");\n        console.println(\"[TRACE] \" + gl.explain(rid));\n        console.println(\"=== Demo Complete ===\");\n    }\n\n    // RECOVERY: only fire when no candidate was accepted (genuine failure)\n    rule -!classified(string foodItem) : ~accepted(string _) {\n        console.println(\"[AGENT] Classification FAILED for \" + foodItem);\n    }\n\n    rule -!deliberated(string rid) : ~accepted(string _) {\n        console.println(\"[AGENT] Deliberation FAILED for \" + rid);\n    }\n}", "jason/acceptance-patterns/pattern-1-simple-validation/src/main/asl/main.asl": "// Pipeline: start > !banner > !classified > !deliberated > !accepted_candidate | !rejected_candidate > !print_trace\n/**\n * Pattern 1: Simple Validation - Jason\n *\n * The simplest governance pattern: record acceptance for valid output, reject invalid output.\n * Demonstrates the fundamental decide() context-guard branching.\n */\n\n// Requires: GL ontology beliefs (gl_status, gl_candidate_type, gl_verdict_type, ...)\n//   See: https://github.com/generativelayers/examples/tree/main/jason/shared\n\n// DOMAIN MODEL\nvalidated(Cid) :- accepted(Cid).\nvalidated(Cid) :- rejected(Cid).\nhas_candidate(Cid) :- Cid \\== \"\".\nno_candidate(Cid)  :- Cid == \"\".\n\n!start.\n\n// DECOMPOSITION: start only adopts subgoals\n+!start\n   <- !banner;\n      gl.bind(\"agent1\", \"groq\", \"openai/gpt-oss-120b\", \"\", Bid);\n      +binding(Bid);\n      !classified(\"apple\");\n      !shutdown.\n\n// ACHIEVEMENT: clean exit\n+!shutdown\n   <- .stopMAS.\n\n// ACHIEVEMENT: display banner\n+!banner\n   :  gl.see(Providers)\n   <- .println(\"=== Pattern 1: Simple Validation ===\");\n      .println(\"\");\n      .println(\"[Layer] Available providers: \", Providers).\n\n// DECOMPOSITION: classify = call + deliberate\n+!classified(FoodItem)\n   :  binding(Bid)\n   <- .concat(\"Classify the food item '\", FoodItem, \"'. Return label and confidence.\", Prompt);\n      gl.call(Bid, \"classify_food\", \"llm.answer\", \"ANSWER\", Prompt, \"label,confidence\", \"\", Rid);\n      !deliberated(Rid).\n\n// SERENDIPITY: already deliberated\n+!deliberated(Rid)\n   :  gl.candidate(Rid, Cid) & validated(Cid)\n   <- .println(\"[AGENT] Already deliberated: \", Rid).\n\n// DECOMPOSITION: admissible > accept + trace\n+!deliberated(Rid)\n   :  gl.candidate(Rid, Cid) & gl.decide(Cid, \"ADMISSIBLE\")\n   <- !accepted_candidate(Rid, Cid);\n      !print_trace(Rid).\n\n// DECOMPOSITION: not admissible > reject + trace\n+!deliberated(Rid)\n   :  gl.candidate(Rid, Cid)\n   <- !rejected_candidate(Cid, Rid);\n      !print_trace(Rid).\n\n// ACHIEVEMENT: accept (actions only)\n+!accepted_candidate(Rid, Cid)\n   :  gl.get(Cid, \"label\", Label) & gl.get(Cid, \"confidence\", Confidence)\n   <- .println(\"\");\n      .println(\"[AGENT] Candidate is ADMISSIBLE.\");\n      .println(\"[AGENT]   label      = \", Label);\n      .println(\"[AGENT]   confidence = \", Confidence);\n      gl.accept(Cid, \"valid classification\", _);\n      +accepted(Cid);\n      +classified(\"food\", Label, Confidence);\n      .println(\"[AGENT] Candidate ACCEPTED. Domain belief added explicitly by the agent program.\").\n\n// ACHIEVEMENT: reject (actions only) - candidate exists\n+!rejected_candidate(Cid, Rid)\n   :  has_candidate(Cid) & gl.explain(Rid, Trace) & gl.decide(Cid, Admissibility)\n   <- gl.reject(Cid, \"failed validation\", _);\n      +rejected(Cid);\n      .println(\"\");\n      .println(\"[AGENT] Candidate REJECTED.\");\n      .println(\"[AGENT]   reason = \", Trace).\n\n// ACHIEVEMENT: reject (actions only) - no candidate\n+!rejected_candidate(Cid, Rid)\n   :  no_candidate(Cid) & gl.result(Rid, Outcome)\n   <- +rejected(\"\");\n      .println(\"\");\n      .println(\"[AGENT] Invocation failed, no candidate.\");\n      .println(\"[AGENT]   outcome = \", Outcome).\n\n// ACHIEVEMENT: print trace\n+!print_trace(Rid)\n   :  gl.explain(Rid, Trace)\n   <- .println(\"\");\n      .println(\"[TRACE] \", Trace);\n      .println(\"=== Demo Complete ===\").\n\n// RECOVERY\n-!classified(FoodItem)\n   :  not accepted(_)\n   <- .println(\"[AGENT] Classification FAILED for \", FoodItem).\n\n-!deliberated(Rid)\n   :  not accepted(_)\n   <- .println(\"[AGENT] Deliberation FAILED for \", Rid).", "jacamo/acceptance-patterns/pattern-1-simple-validation/src/agt/main.asl": "// Pipeline: start > !artifact_ready > !banner > !setup > !classified > !deliberated > !accepted_candidate | !rejected_candidate > !print_trace\n/**\n * Pattern 1: Simple Validation - JaCaMo\n *\n * The simplest governance pattern: record acceptance for valid output, reject invalid output.\n * Demonstrates the fundamental decide() context-guard branching.\n */\n\n// DOMAIN MODEL\nvalidated(Cid) :- accepted(Cid).\nvalidated(Cid) :- rejected(Cid).\nhas_candidate(Cid) :- Cid \\== \"\".\nno_candidate(Cid)  :- Cid == \"\".\n\n!start.\n\n// DECOMPOSITION: start only adopts subgoals\n+!start\n   <- !artifact_ready;\n      !banner;\n      !setup;\n      !classified(\"apple\");\n      .stopMAS.\n\n// ACHIEVEMENT: create and focus the GL artifact\n+!artifact_ready\n   <- makeArtifact(\"gl\", \"gl.jacamo.GL\", [], GlId);\n      focus(GlId).\n\n// ACHIEVEMENT: display banner\n+!banner\n   <- see(Providers);\n      .println(\"=== Pattern 1: Simple Validation ===\");\n      .println(\"\");\n      .println(\"[Layer] Available providers: \", Providers).\n\n// ACHIEVEMENT: setup (actions only)\n+!setup\n   <- bind(\"agent1\", \"groq\", \"openai/gpt-oss-120b\", \"\", Bid);\n      +binding(Bid).\n\n// DECOMPOSITION: classify = call + deliberate\n+!classified(FoodItem)\n   :  binding(Bid)\n   <- .concat(\"Classify the food item '\", FoodItem, \"'. Return label and confidence.\", Prompt);\n      call(Bid, \"classify_food\", \"llm.answer\", \"ANSWER\", Prompt, \"label,confidence\", \"\", Rid);\n      !deliberated(Rid).\n\n// DECOMPOSITION: handle deliberation based on outcome\n+!deliberated(Rid)\n   <- candidate(Rid, Cid);\n      !deliberated_candidate(Rid, Cid).\n\n+!deliberated_candidate(Rid, Cid)\n   :  has_candidate(Cid)\n   <- decide(Cid, Admissibility);\n      !deliberated_decision(Rid, Cid, Admissibility).\n\n+!deliberated_candidate(Rid, Cid)\n   :  no_candidate(Cid)\n   <- result(Rid, Outcome);\n      !deliberated_decision(Rid, Cid, Outcome).\n\n// DECOMPOSITION: route decision\n+!deliberated_decision(Rid, Cid, \"ADMISSIBLE\")\n   <- !accepted_candidate(Rid, Cid);\n      !print_trace(Rid).\n\n+!deliberated_decision(Rid, Cid, Outcome)\n   <- !rejected_candidate(Cid, Rid, Outcome);\n      !print_trace(Rid).\n\n// ACHIEVEMENT: accept (actions only)\n+!accepted_candidate(Rid, Cid)\n   <- get(Cid, \"label\", Label);\n      get(Cid, \"confidence\", Confidence);\n      .println(\"\");\n      .println(\"[AGENT] Candidate is ADMISSIBLE.\");\n      .println(\"[AGENT]   label      = \", Label);\n      .println(\"[AGENT]   confidence = \", Confidence);\n      accept(Cid, \"valid classification\", _);\n      +accepted(Cid);\n      +classified(\"food\", Label, Confidence);\n      .println(\"[AGENT] Candidate ACCEPTED. Domain belief added explicitly by the agent program.\").\n\n// ACHIEVEMENT: reject (actions only) - candidate exists\n+!rejected_candidate(Cid, Rid, Outcome)\n   :  has_candidate(Cid)\n   <- reject(Cid, \"failed validation\", _);\n      +rejected(Cid);\n      explain(Rid, Trace);\n      .println(\"\");\n      .println(\"[AGENT] Candidate REJECTED.\");\n      .println(\"[AGENT]   reason = \", Trace).\n\n// ACHIEVEMENT: reject (actions only) - no candidate\n+!rejected_candidate(Cid, Rid, Outcome)\n   :  no_candidate(Cid)\n   <- +rejected(\"\");\n      .println(\"\");\n      .println(\"[AGENT] Invocation failed, no candidate.\");\n      .println(\"[AGENT]   outcome = \", Outcome).\n\n// ACHIEVEMENT: print trace\n+!print_trace(Rid)\n   <- explain(Rid, Trace);\n      .println(\"\");\n      .println(\"[TRACE] \", Trace);\n      .println(\"=== Demo Complete ===\").\n\n// RECOVERY\n-!classified(FoodItem)\n   :  not accepted(_)\n   <- .println(\"[AGENT] Classification FAILED for \", FoodItem).\n\n-!deliberated(Rid)\n   :  not accepted(_)\n   <- .println(\"[AGENT] Deliberation FAILED for \", Rid).", "astra/acceptance-patterns/pattern-2-content-inspection/src/main/astra/PatternRunner.astra": "// Pipeline: main > !inspected > !known_category > ?inspected\n// Pattern 2: Content Inspection - ASTRA\n//\n// After validation, inspects the LLM output against the agent's\n// own knowledge base. Records acceptance only if the label is a known category.\nagent PatternRunner {\n    module gl.astra.GL gl;\n    module Console console;\n    module System S;\n\n    types governance {\n        formula binding(string);\n        formula inspected(string);\n        formula accepted(string);\n        formula rejected(string);\n        formula known(string);\n    }\n\n    initial known(\"fruit\"), known(\"vegetable\"), known(\"grain\");\n\n    // DOMAIN MODEL\n    inference inspected(string cid) :- accepted(cid);\n    inference inspected(string cid) :- rejected(cid);\n\n    // DECOMPOSITION: main only adopts subgoals\n    rule +!main(list args) {\n        !banner();\n        !setup();\n        !classified(\"apple\");\n        !shutdown();\n    }\n\n    // ACHIEVEMENT: display banner\n    rule +!banner() {\n        console.println(\"=== Pattern 2: Content Inspection ===\");\n        console.println(\"\");\n    }\n\n    // ACHIEVEMENT: setup binding\n    rule +!setup() {\n        +binding(gl.bind(\"agent1\", \"groq\", \"openai/gpt-oss-120b\", \"\"));\n    }\n\n    // ACHIEVEMENT: clean exit\n    rule +!shutdown() {\n        S.exit();\n    }\n\n    // DECOMPOSITION: classify = call + inspect\n    rule +!classified(string item) : binding(string bid) {\n        !inspected(gl.call(bid, \"classify\", \"llm.answer\", \"ANSWER\",\n            \"Classify: \" + item + \". Return label and confidence.\",\n            \"label,confidence\", \"category(\" + item + \", fruit)\"));\n    }\n\n    // SERENDIPITY: already inspected\n    rule +!inspected(string rid) : inspected(gl.candidate(rid)) {\n        console.println(\"Already inspected: \" + rid);\n    }\n\n    // DECOMPOSITION: admissible > check content against knowledge base\n    rule +!inspected(string rid) : gl.decide(gl.candidate(rid)) == \"ADMISSIBLE\" {\n        !known_category(rid, gl.candidate(rid), gl.get(gl.candidate(rid), \"label\"));\n    }\n\n    // ACHIEVEMENT: not admissible > reject\n    rule +!inspected(string rid) {\n        gl.reject(gl.candidate(rid), \"output not admissible\");\n        +rejected(gl.candidate(rid));\n        console.println(\"Invalid output - REJECTED\");\n    }\n\n    // ACHIEVEMENT: known category > accept\n    rule +!known_category(string rid, string cid, string label) : known(label) {\n        gl.accept(cid, \"known category: \" + label);\n        +accepted(cid);\n        console.println(\"Known category '\" + label + \"' - ACCEPTED\");\n        console.println(\"  confidence = \" + gl.get(cid, \"confidence\"));\n        console.println(\"\");\n        console.println(\"[TRACE] \" + gl.explain(rid));\n        console.println(\"=== Demo Complete ===\");\n    }\n\n    // ACHIEVEMENT: unknown category > reject\n    rule +!known_category(string rid, string cid, string label) : ~known(label) {\n        gl.reject(cid, \"unknown category: \" + label);\n        +rejected(cid);\n        console.println(\"Unknown category '\" + label + \"' - REJECTED\");\n        console.println(\"\");\n        console.println(\"[TRACE] \" + gl.explain(rid));\n        console.println(\"=== Demo Complete ===\");\n    }\n\n    // RECOVERY\n    rule -!inspected(string rid) : ~accepted(string _) & ~rejected(string _) {\n        console.println(\"Inspection FAILED for \" + rid);\n    }\n}", "jason/acceptance-patterns/pattern-2-content-inspection/src/main/asl/main.asl": "// Pipeline: start > !banner > !setup > !classified > !inspected > !known_category\n/**\n * Pattern 2: Content Inspection - Jason\n *\n * After validation, inspects the LLM output against the agent's\n * own knowledge base. Records acceptance only if the label is a known category.\n */\n\n// Requires: GL ontology beliefs (gl_status, gl_candidate_type, gl_verdict_type, ...)\n//   See: https://github.com/generativelayers/examples/tree/main/jason/shared\n\nknown(\"fruit\"). known(\"vegetable\"). known(\"grain\").\n\n// DOMAIN MODEL\ninspected(Cid) :- accepted(Cid).\ninspected(Cid) :- rejected(Cid).\nhas_candidate(Cid) :- Cid \\== \"\".\nno_candidate(Cid)  :- Cid == \"\".\n\n!start.\n\n// DECOMPOSITION: start only adopts subgoals\n+!start\n   <- !banner;\n      !setup;\n      !classified(\"apple\");\n      !shutdown.\n\n// ACHIEVEMENT: setup binding\n+!setup\n   <- gl.bind(\"agent1\", \"groq\", \"openai/gpt-oss-120b\", \"\", Bid);\n      +binding(Bid);\n      ?binding(Bid).\n\n// ACHIEVEMENT: clean exit\n+!shutdown\n   <- .stopMAS.\n\n// ACHIEVEMENT: display banner\n+!banner\n   <- .println(\"=== Pattern 2: Content Inspection ===\");\n      .println(\"\").\n\n// DECOMPOSITION: classify = call + inspect\n+!classified(Item)\n   :  binding(Bid)\n   <- .concat(\"Classify: \", Item, \". Return label and confidence.\", Prompt);\n      .concat(\"category(\", Item, \", fruit)\", Context);\n      gl.call(Bid, \"classify\", \"llm.answer\", \"ANSWER\", Prompt, \"label,confidence\", Context, Rid);\n      !inspected(Rid).\n\n// SERENDIPITY: already inspected\n+!inspected(Rid)\n   :  gl.candidate(Rid, Cid) & inspected(Cid)\n   <- .println(\"Already inspected: \", Rid).\n\n// DECOMPOSITION: admissible > check content against knowledge base\n+!inspected(Rid)\n   :  gl.candidate(Rid, Cid) & gl.decide(Cid, \"ADMISSIBLE\") & gl.get(Cid, \"label\", Label)\n   <- !known_category(Rid, Cid, Label).\n\n// DECOMPOSITION: not admissible > reject\n+!inspected(Rid)\n   :  gl.candidate(Rid, Cid)\n   <- !rejected_candidate(Cid, Rid);\n      !print_trace(Rid).\n\n// ACHIEVEMENT: known category > accept\n+!known_category(Rid, Cid, Label)\n   :  known(Label) & gl.get(Cid, \"confidence\", Confidence)\n   <- .concat(\"known category: \", Label, Reason);\n      gl.accept(Cid, Reason, _);\n      +accepted(Cid);\n      .println(\"Known category '\", Label, \"' - ACCEPTED\");\n      .println(\"  confidence = \", Confidence);\n      .println(\"\");\n      !print_trace(Rid).\n\n// ACHIEVEMENT: unknown category > reject\n+!known_category(Rid, Cid, Label)\n   :  not known(Label)\n   <- .concat(\"unknown category: \", Label, Reason);\n      gl.reject(Cid, Reason, _);\n      +rejected(Cid);\n      .println(\"Unknown category '\", Label, \"' - REJECTED\");\n      .println(\"\");\n      !print_trace(Rid).\n\n// ACHIEVEMENT: reject (actions only) - candidate exists\n+!rejected_candidate(Cid, Rid)\n   :  has_candidate(Cid)\n   <- gl.reject(Cid, \"output not admissible\", _);\n      +rejected(Cid);\n      .println(\"Invalid output - REJECTED\").\n\n// ACHIEVEMENT: reject (actions only) - no candidate\n+!rejected_candidate(Cid, Rid)\n   :  no_candidate(Cid) & gl.result(Rid, Outcome)\n   <- +rejected(\"\");\n      .println(\"Invocation failed, no candidate - REJECTED (outcome = \", Outcome, \")\").\n\n// ACHIEVEMENT: print trace\n+!print_trace(Rid)\n   :  gl.explain(Rid, Trace)\n   <- .println(\"\");\n      .println(\"[TRACE] \", Trace);\n      .println(\"=== Demo Complete ===\").\n\n// RECOVERY\n-!inspected(Rid)\n   :  not accepted(_) & not rejected(_)\n   <- .println(\"Inspection FAILED for \", Rid).", "jacamo/acceptance-patterns/pattern-2-content-inspection/src/agt/main.asl": "// Pipeline: start > !banner > !setup > !classified > !inspected > !known_category\n/**\n * Pattern 2: Content Inspection - JaCaMo\n *\n * After validation, inspects the LLM output against the agent's\n * own knowledge base. Records acceptance only if the label is a known category.\n */\n\nknown(\"fruit\"). known(\"vegetable\"). known(\"grain\").\n\n// DOMAIN MODEL\ninspected(Cid) :- accepted(Cid).\ninspected(Cid) :- rejected(Cid).\nhas_candidate(Cid) :- Cid \\== \"\".\nno_candidate(Cid)  :- Cid == \"\".\n\n!start.\n\n// DECOMPOSITION: start only adopts subgoals\n+!start\n   <- !artifact_ready;\n      !banner;\n      !setup;\n      !classified(\"apple\");\n      .stopMAS.\n\n// ACHIEVEMENT: create and focus the GL artifact\n+!artifact_ready\n   <- makeArtifact(\"gl\", \"gl.jacamo.GL\", [], GlId);\n      focus(GlId).\n\n// ACHIEVEMENT: display banner\n+!banner\n   <- see(Providers);\n      .println(\"=== Pattern 2: Content Inspection ===\");\n      .println(\"\").\n\n// ACHIEVEMENT: setup\n+!setup\n   <- bind(\"agent1\", \"groq\", \"openai/gpt-oss-120b\", \"\", Bid);\n      +binding(Bid).\n\n// DECOMPOSITION: classify = call + inspect\n+!classified(Item)\n   :  binding(Bid)\n   <- .concat(\"Classify: \", Item, \". Return label and confidence.\", Prompt);\n      .concat(\"category(\", Item, \", fruit)\", Context);\n      call(Bid, \"classify\", \"llm.answer\", \"ANSWER\", Prompt, \"label,confidence\", Context, Rid);\n      !inspected(Rid).\n\n// SERENDIPITY: already inspected\n+!inspected(Rid)\n   :  accepted(Cid) & candidate(Rid, Cid)\n   <- .println(\"Already inspected: \", Rid).\n\n// DECOMPOSITION: handle deliberation\n+!inspected(Rid)\n   <- candidate(Rid, Cid);\n      !inspected_candidate(Rid, Cid).\n\n+!inspected_candidate(Rid, Cid)\n   :  has_candidate(Cid)\n   <- decide(Cid, Admissibility);\n      !inspected_decision(Rid, Cid, Admissibility).\n\n+!inspected_candidate(Rid, Cid)\n   :  no_candidate(Cid)\n   <- result(Rid, Outcome);\n      !inspected_decision(Rid, Cid, Outcome).\n\n// DECOMPOSITION: route decision\n+!inspected_decision(Rid, Cid, \"ADMISSIBLE\")\n   <- get(Cid, \"label\", Label);\n      !known_category(Rid, Cid, Label).\n\n+!inspected_decision(Rid, Cid, Outcome)\n   <- !rejected_candidate(Cid, Rid, Outcome);\n      !print_trace(Rid).\n\n// ACHIEVEMENT: known category > accept\n+!known_category(Rid, Cid, Label)\n   :  known(Label)\n   <- get(Cid, \"confidence\", Confidence);\n      .concat(\"known category: \", Label, Reason);\n      accept(Cid, Reason, _);\n      +accepted(Cid);\n      .println(\"Known category '\", Label, \"' - ACCEPTED\");\n      .println(\"  confidence = \", Confidence);\n      .println(\"\");\n      !print_trace(Rid).\n\n// ACHIEVEMENT: unknown category > reject\n+!known_category(Rid, Cid, Label)\n   :  not known(Label)\n   <- .concat(\"unknown category: \", Label, Reason);\n      reject(Cid, Reason, _);\n      +rejected(Cid);\n      .println(\"Unknown category '\", Label, \"' - REJECTED\");\n      .println(\"\");\n      !print_trace(Rid).\n\n// ACHIEVEMENT: reject (actions only) - candidate exists\n+!rejected_candidate(Cid, Rid, Outcome)\n   :  has_candidate(Cid)\n   <- reject(Cid, \"output not admissible\", _);\n      +rejected(Cid);\n      .println(\"Invalid output - REJECTED\").\n\n// ACHIEVEMENT: reject (actions only) - no candidate\n+!rejected_candidate(Cid, Rid, Outcome)\n   :  no_candidate(Cid)\n   <- +rejected(\"\");\n      .println(\"Invocation failed, no candidate - REJECTED (outcome = \", Outcome, \")\").\n\n// ACHIEVEMENT: print trace\n+!print_trace(Rid)\n   <- explain(Rid, Trace);\n      .println(\"\");\n      .println(\"[TRACE] \", Trace);\n      .println(\"=== Demo Complete ===\").\n\n// RECOVERY\n-!inspected(Rid)\n   :  not accepted(_) & not rejected(_)\n   <- .println(\"Inspection FAILED for \", Rid).", "astra/acceptance-patterns/pattern-3-confidence-threshold/src/main/astra/PatternRunner.astra": "// Pipeline: main > !classified > !assessed > !assess_confidence\n// Pattern 3: Confidence Tier - ASTRA\n//\n// Use a categorical confidence tier: high accepts, low rejects,\n// and medium/unknown escalates.\nagent PatternRunner {\n    module gl.astra.GL gl;\n    module Console console;\n    module System S;\n\n    types governance {\n        formula binding(string);\n        formula assessed(string);\n        formula accepted(string);\n        formula rejected(string);\n        formula escalated(string);\n        formula confidence_tier(string, string);\n    }\n\n    inference assessed(string cid) :- accepted(cid);\n    inference assessed(string cid) :- rejected(cid);\n    inference assessed(string cid) :- escalated(cid);\n\n    rule +!main(list args) {\n        !banner();\n        +binding(gl.bind(\"agent1\", \"groq\", \"openai/gpt-oss-120b\", \"\"));\n        !classified(\"apple\");\n        !shutdown();\n    }\n\n    // ACHIEVEMENT: clean exit\n    rule +!shutdown() {\n        S.exit();\n    }\n\n    // ACHIEVEMENT: display banner\n    rule +!banner() {\n        console.println(\"=== Pattern 3: Confidence Tier ===\");\n        console.println(\"\");\n        console.println(\"[Layer] Available providers: \" + gl.see());\n    }\n\n    // DECOMPOSITION: classify = call + deliberate/assess\n    rule +!classified(string item) : binding(string bid) {\n        !assessed(gl.call(bid, \"classify\", \"llm.answer\", \"ANSWER\",\n            \"Classify: \" + item + \". Return label and confidence_tier: high, medium, or low.\",\n            \"label,confidence_tier\", \"\"));\n    }\n\n    // SERENDIPITY: already assessed\n    rule +!assessed(string rid) : assessed(gl.candidate(rid)) {\n        console.println(\"[AGENT] Already assessed: \" + rid);\n    }\n\n    // DECOMPOSITION: admissible > check confidence tier\n    rule +!assessed(string rid) : gl.decide(gl.candidate(rid)) == \"ADMISSIBLE\" {\n        !assess_confidence(rid, gl.candidate(rid), gl.get(gl.candidate(rid), \"confidence_tier\"));\n        !print_trace(rid);\n    }\n\n    // DECOMPOSITION: not admissible > reject\n    rule +!assessed(string rid) {\n        !rejected_candidate(gl.candidate(rid), rid);\n        !print_trace(rid);\n    }\n\n    // ACHIEVEMENT: high confidence > accept\n    rule +!assess_confidence(string rid, string cid, string tier) : tier == \"high\" {\n        gl.accept(cid, \"high confidence\");\n        +accepted(cid);\n        +confidence_tier(cid, \"high\");\n        console.println(\"High confidence - ACCEPTED\");\n        console.println(\"  label = \" + gl.get(cid, \"label\"));\n        console.println(\"=== Demo Complete ===\");\n    }\n\n    // ACHIEVEMENT: low confidence > reject\n    rule +!assess_confidence(string rid, string cid, string tier) : tier == \"low\" {\n        gl.reject(cid, \"low confidence\");\n        +rejected(cid);\n        +confidence_tier(cid, \"low\");\n        console.println(\"Low confidence - REJECTED\");\n        console.println(\"=== Demo Complete ===\");\n    }\n\n    // ACHIEVEMENT: medium/other > escalate\n    rule +!assess_confidence(string rid, string cid, string tier) {\n        +escalated(cid);\n        +confidence_tier(cid, tier);\n        console.println(\"Confidence tier '\" + tier + \"' - ESCALATING\");\n        console.println(\"=== Demo Complete ===\");\n    }\n\n    // ACHIEVEMENT: reject (actions only)\n    rule +!rejected_candidate(string cid, string rid) {\n        gl.reject(cid, \"failed validation\");\n        +rejected(cid);\n        console.println(\"Invalid output - REJECTED\");\n    }\n\n    // ACHIEVEMENT: print trace\n    rule +!print_trace(string rid) {\n        console.println(\"\");\n        console.println(\"[TRACE] \" + gl.explain(rid));\n    }\n\n    // RECOVERY\n    rule -!assessed(string rid) : ~accepted(string _) & ~rejected(string _) & ~escalated(string _) {\n        console.println(\"Assessment FAILED for \" + rid);\n    }\n}", "jason/acceptance-patterns/pattern-3-confidence-threshold/src/main/asl/main.asl": "// Pipeline: start > !banner > !classified > !assessed > !assess_confidence | !rejected_candidate\n/**\n * Pattern 3: Confidence Tier - Jason\n *\n * Use a categorical confidence tier: high accepts, low rejects,\n * and medium/unknown escalates.\n */\n\n// Requires: GL ontology beliefs (gl_status, gl_candidate_type, gl_verdict_type, ...)\n//   See: https://github.com/generativelayers/examples/tree/main/jason/shared\n\n// DOMAIN MODEL\nassessed(Cid) :- accepted(Cid).\nassessed(Cid) :- rejected(Cid).\nassessed(Cid) :- escalated(Cid).\nhas_candidate(Cid) :- Cid \\== \"\".\nno_candidate(Cid)  :- Cid == \"\".\n\n!start.\n\n// DECOMPOSITION: start only adopts subgoals\n+!start\n   <- !banner;\n      gl.bind(\"agent1\", \"groq\", \"openai/gpt-oss-120b\", \"\", Bid);\n      +binding(Bid);\n      !classified(\"apple\");\n      !shutdown.\n\n// ACHIEVEMENT: clean exit\n+!shutdown\n   <- .stopMAS.\n\n// ACHIEVEMENT: display banner\n+!banner\n   :  gl.see(Providers)\n   <- .println(\"=== Pattern 3: Confidence Tier ===\");\n      .println(\"\");\n      .println(\"[Layer] Available providers: \", Providers).\n\n// DECOMPOSITION: classify = call + deliberate/assess\n+!classified(Item)\n   :  binding(Bid)\n   <- .concat(\"Classify: \", Item, \". Return label and confidence_tier: high, medium, or low.\", Prompt);\n      gl.call(Bid, \"classify\", \"llm.answer\", \"ANSWER\", Prompt, \"label,confidence_tier\", \"\", Rid);\n      !assessed(Rid).\n\n// SERENDIPITY: already assessed\n+!assessed(Rid)\n   :  gl.candidate(Rid, Cid) & assessed(Cid)\n   <- .println(\"[AGENT] Already assessed: \", Rid).\n\n// DECOMPOSITION: admissible > check confidence tier\n+!assessed(Rid)\n   :  gl.candidate(Rid, Cid) & gl.decide(Cid, \"ADMISSIBLE\") & gl.get(Cid, \"confidence_tier\", Tier)\n   <- !assess_confidence(Rid, Cid, Tier);\n      !print_trace(Rid).\n\n// DECOMPOSITION: not admissible > reject\n+!assessed(Rid)\n   :  gl.candidate(Rid, Cid)\n   <- !rejected_candidate(Cid, Rid);\n      !print_trace(Rid).\n\n// ACHIEVEMENT: high confidence > accept\n+!assess_confidence(Rid, Cid, \"high\")\n   :  gl.get(Cid, \"label\", Label)\n   <- gl.accept(Cid, \"high confidence\", _);\n      +accepted(Cid);\n      +confidence_tier(Cid, \"high\");\n      .println(\"High confidence - ACCEPTED\");\n      .println(\"  label = \", Label).\n\n// ACHIEVEMENT: low confidence > reject\n+!assess_confidence(Rid, Cid, \"low\")\n   <- gl.reject(Cid, \"low confidence\", _);\n      +rejected(Cid);\n      +confidence_tier(Cid, \"low\");\n      .println(\"Low confidence - REJECTED\").\n\n// ACHIEVEMENT: medium/other > escalate\n+!assess_confidence(Rid, Cid, Tier)\n   <- +escalated(Cid);\n      +confidence_tier(Cid, Tier);\n      .println(\"Confidence tier '\", Tier, \"' - ESCALATING\").\n\n// ACHIEVEMENT: reject (actions only) - candidate exists\n+!rejected_candidate(Cid, Rid)\n   :  has_candidate(Cid)\n   <- gl.reject(Cid, \"failed validation\", _);\n      +rejected(Cid);\n      .println(\"Invalid output - REJECTED\").\n\n// ACHIEVEMENT: reject (actions only) - no candidate\n+!rejected_candidate(Cid, Rid)\n   :  no_candidate(Cid) & gl.result(Rid, Outcome)\n   <- +rejected(\"\");\n      .println(\"Invocation failed, no candidate - REJECTED (outcome = \", Outcome, \")\").\n\n// ACHIEVEMENT: print trace\n+!print_trace(Rid)\n   :  gl.explain(Rid, Trace)\n   <- .println(\"\");\n      .println(\"[TRACE] \", Trace).\n\n// RECOVERY\n-!assessed(Rid)\n   :  not accepted(_) & not rejected(_) & not escalated(_)\n   <- .println(\"Assessment FAILED for \", Rid).", "jacamo/acceptance-patterns/pattern-3-confidence-threshold/src/agt/main.asl": "// Pipeline: start > !banner > !setup > !classified > !assessed > !assess_confidence | !rejected_candidate\n/**\n * Pattern 3: Confidence Tier - JaCaMo\n *\n * Use a categorical confidence tier: high accepts, low rejects,\n * and medium/unknown escalates.\n */\n\n// DOMAIN MODEL\nassessed(Cid) :- accepted(Cid).\nassessed(Cid) :- rejected(Cid).\nassessed(Cid) :- escalated(Cid).\nhas_candidate(Cid) :- Cid \\== \"\".\nno_candidate(Cid)  :- Cid == \"\".\n\n!start.\n\n// DECOMPOSITION: start only adopts subgoals\n+!start\n   <- !artifact_ready;\n      !banner;\n      !setup;\n      !classified(\"apple\");\n      .stopMAS.\n\n// ACHIEVEMENT: create and focus the GL artifact\n+!artifact_ready\n   <- makeArtifact(\"gl\", \"gl.jacamo.GL\", [], GlId);\n      focus(GlId).\n\n// ACHIEVEMENT: display banner\n+!banner\n   <- see(Providers);\n      .println(\"=== Pattern 3: Confidence Tier ===\");\n      .println(\"\").\n\n// ACHIEVEMENT: setup\n+!setup\n   <- bind(\"agent1\", \"groq\", \"openai/gpt-oss-120b\", \"\", Bid);\n      +binding(Bid).\n\n// DECOMPOSITION: classify = call + deliberate/assess\n+!classified(Item)\n   :  binding(Bid)\n   <- .concat(\"Classify: \", Item, \". Return label and confidence_tier: high, medium, or low.\", Prompt);\n      call(Bid, \"classify\", \"llm.answer\", \"ANSWER\", Prompt, \"label,confidence_tier\", \"\", Rid);\n      !assessed(Rid).\n\n// SERENDIPITY: already assessed\n+!assessed(Rid)\n   :  accepted(Cid) & candidate(Rid, Cid)\n   <- .println(\"Already assessed: \", Rid).\n\n// DECOMPOSITION: handle deliberation\n+!assessed(Rid)\n   <- candidate(Rid, Cid);\n      !assessed_candidate(Rid, Cid).\n\n+!assessed_candidate(Rid, Cid)\n   :  has_candidate(Cid)\n   <- decide(Cid, Admissibility);\n      !assessed_decision(Rid, Cid, Admissibility).\n\n+!assessed_candidate(Rid, Cid)\n   :  no_candidate(Cid)\n   <- result(Rid, Outcome);\n      !assessed_decision(Rid, Cid, Outcome).\n\n// DECOMPOSITION: route decision\n+!assessed_decision(Rid, Cid, \"ADMISSIBLE\")\n   <- get(Cid, \"confidence_tier\", Tier);\n      !assess_confidence(Rid, Cid, Tier);\n      !print_trace(Rid).\n\n+!assessed_decision(Rid, Cid, Outcome)\n   <- !rejected_candidate(Cid, Rid, Outcome);\n      !print_trace(Rid).\n\n// ACHIEVEMENT: high confidence > accept\n+!assess_confidence(Rid, Cid, \"high\")\n   <- get(Cid, \"label\", Label);\n      accept(Cid, \"high confidence\", _);\n      +accepted(Cid);\n      +confidence_tier(Cid, \"high\");\n      .println(\"High confidence - ACCEPTED\");\n      .println(\"  label = \", Label).\n\n// ACHIEVEMENT: low confidence > reject\n+!assess_confidence(Rid, Cid, \"low\")\n   <- reject(Cid, \"low confidence\", _);\n      +rejected(Cid);\n      +confidence_tier(Cid, \"low\");\n      .println(\"Low confidence - REJECTED\").\n\n// ACHIEVEMENT: medium/other > escalate\n+!assess_confidence(Rid, Cid, Tier)\n   <- +escalated(Cid);\n      +confidence_tier(Cid, Tier);\n      .println(\"Confidence tier '\", Tier, \"' - ESCALATING\").\n\n// ACHIEVEMENT: reject (actions only) - candidate exists\n+!rejected_candidate(Cid, Rid, Outcome)\n   :  has_candidate(Cid)\n   <- reject(Cid, \"failed validation\", _);\n      +rejected(Cid);\n      .println(\"Invalid output - REJECTED\").\n\n// ACHIEVEMENT: reject (actions only) - no candidate\n+!rejected_candidate(Cid, Rid, Outcome)\n   :  no_candidate(Cid)\n   <- +rejected(\"\");\n      .println(\"Invocation failed, no candidate - REJECTED (outcome = \", Outcome, \")\").\n\n// ACHIEVEMENT: print trace\n+!print_trace(Rid)\n   <- explain(Rid, Trace);\n      .println(\"\");\n      .println(\"[TRACE] \", Trace).\n\n// RECOVERY\n-!assessed(Rid)\n   :  not accepted(_) & not rejected(_) & not escalated(_)\n   <- .println(\"Assessment FAILED for \", Rid).", "astra/acceptance-patterns/pattern-4-cross-llm-verification/src/main/astra/PatternRunner.astra": "// Pipeline: main > !classified > !verified > !cross_check > !evaluate_verifier > !match_labels\n// Pattern 4: Cross-LLM Verification - ASTRA\n//\n// Use a primary provider and a verifier provider; accept only\n// when both candidates agree.\nagent PatternRunner {\n    module gl.astra.GL gl;\n    module Console console;\n    module System S;\n\n    types governance {\n        formula primary_binding(string);\n        formula verifier_binding(string);\n        formula verified(string);\n        formula accepted(string);\n        formula rejected(string);\n    }\n\n    inference verified(string cid) :- accepted(cid);\n    inference verified(string cid) :- rejected(cid);\n\n    rule +!main(list args) {\n        !banner();\n        +primary_binding(gl.bind(\"agent1\", \"groq\", \"openai/gpt-oss-120b\", \"\"));\n        +verifier_binding(gl.bind(\"verifier1\", \"cerebras\", \"gpt-oss-120b\", \"\"));\n        !classified(\"apple\");\n        !shutdown();\n    }\n\n    // ACHIEVEMENT: clean exit\n    rule +!shutdown() {\n        S.exit();\n    }\n\n    // ACHIEVEMENT: display banner\n    rule +!banner() {\n        console.println(\"=== Pattern 4: Cross-LLM Verification ===\");\n        console.println(\"\");\n        console.println(\"[Layer] Available providers: \" + gl.see());\n    }\n\n    // DECOMPOSITION: classify = call + inspect\n    rule +!classified(string item) : primary_binding(string bid) & verifier_binding(string vbid) {\n        !verified(gl.call(bid, \"classify\", \"llm.answer\", \"ANSWER\",\n            \"Classify: \" + item + \". Return only a label field.\", \"label\", \"\"), item, bid, vbid);\n    }\n\n    // SERENDIPITY: already verified\n    rule +!verified(string rid, string item, string bid, string vbid) : verified(gl.candidate(rid)) {\n        console.println(\"[AGENT] Already verified: \" + rid);\n    }\n\n    // DECOMPOSITION: admissible > check verifier output\n    rule +!verified(string rid, string item, string bid, string vbid) : gl.decide(gl.candidate(rid)) == \"ADMISSIBLE\" {\n        !cross_check(rid, gl.candidate(rid), gl.get(gl.candidate(rid), \"label\"), item, bid, vbid);\n    }\n\n    // DECOMPOSITION: not admissible > reject\n    rule +!verified(string rid, string item, string bid, string vbid) {\n        !rejected_primary(gl.candidate(rid), rid);\n    }\n\n    // DECOMPOSITION: cross-check with verifier\n    rule +!cross_check(string rid, string primaryCid, string primaryLabel, string item, string bid, string vbid) {\n        !evaluate_verifier(rid, primaryCid, primaryLabel,\n            gl.call(vbid, \"verify\", \"llm.answer\", \"ANSWER\",\n                \"Classify this item and return only a label field: \" + item, \"label\", \"\"),\n            item);\n    }\n\n    // DECOMPOSITION: verifier admissible > compare labels\n    rule +!evaluate_verifier(string rid, string primaryCid, string primaryLabel, string vrid, string item) :\n            gl.decide(gl.candidate(vrid)) == \"ADMISSIBLE\" {\n        console.println(\"Primary Agent: label = \" + primaryLabel);\n        console.println(\"Verifier Agent: label = \" + gl.get(gl.candidate(vrid), \"label\"));\n        !match_labels(rid, primaryCid, primaryLabel, vrid, gl.candidate(vrid), gl.get(gl.candidate(vrid), \"label\"));\n    }\n\n    // DECOMPOSITION: verifier not admissible > reject\n    rule +!evaluate_verifier(string rid, string primaryCid, string primaryLabel, string vrid, string item) {\n        !rejected_verifier(primaryCid, gl.candidate(vrid), rid, vrid);\n    }\n\n    // ACHIEVEMENT: labels match > accept both\n    rule +!match_labels(string rid, string primaryCid, string primaryLabel, string vrid, string verifierCid, string verifierLabel) : primaryLabel == verifierLabel {\n        gl.accept(primaryCid, \"cross-LLM match: \" + primaryLabel);\n        gl.accept(verifierCid, \"cross-LLM match: \" + verifierLabel);\n        +accepted(primaryCid);\n        +accepted(verifierCid);\n        console.println(\"Result: MATCH - ACCEPTED\");\n        !print_trace(rid);\n        !print_trace(vrid);\n        console.println(\"=== Demo Complete ===\");\n    }\n\n    // ACHIEVEMENT: labels mismatch > reject both\n    rule +!match_labels(string rid, string primaryCid, string primaryLabel, string vrid, string verifierCid, string verifierLabel) {\n        gl.reject(primaryCid, \"cross-LLM mismatch: \" + primaryLabel + \" vs \" + verifierLabel);\n        gl.reject(verifierCid, \"cross-LLM mismatch: \" + primaryLabel + \" vs \" + verifierLabel);\n        +rejected(primaryCid);\n        +rejected(verifierCid);\n        console.println(\"Result: MISMATCH - REJECTED\");\n        !print_trace(rid);\n        !print_trace(vrid);\n        console.println(\"=== Demo Complete ===\");\n    }\n\n    // ACHIEVEMENT: reject primary only (actions only)\n    rule +!rejected_primary(string cid, string rid) {\n        gl.reject(cid, \"primary validation failed\");\n        +rejected(cid);\n        console.println(\"Invalid primary output - REJECTED\");\n        !print_trace(rid);\n    }\n\n    // ACHIEVEMENT: reject both due to verifier invalid (actions only)\n    rule +!rejected_verifier(string primaryCid, string verifierCid, string rid, string vrid) {\n        gl.reject(primaryCid, \"verifier validation failed\");\n        gl.reject(verifierCid, \"verifier validation failed\");\n        +rejected(primaryCid);\n        +rejected(verifierCid);\n        console.println(\"Verifier output invalid - REJECTED\");\n        !print_trace(rid);\n        !print_trace(vrid);\n    }\n\n    // ACHIEVEMENT: print trace\n    rule +!print_trace(string rid) {\n        console.println(\"\");\n        console.println(\"[TRACE] \" + gl.explain(rid));\n    }\n\n    // RECOVERY\n    rule -!verified(string rid, string item, string bid, string vbid) : ~accepted(string _) & ~rejected(string _) {\n        console.println(\"Verification FAILED for \" + rid);\n    }\n}\n\n// NOTE: To make verification deterministic, you can configure the temperature parameter.\n// Pass \"temperature=0.0\" inside the configuration string (4th argument of the bind call):\n//\n// +primary_binding(gl.bind(\"agent1\", \"groq\", \"openai/gpt-oss-120b\", \"temperature=0.0\"));\n// +verifier_binding(gl.bind(\"verifier1\", \"cerebras\", \"gpt-oss-120b\", \"temperature=0.0\"));\n//\n// Temperature levels control model randomness:\n// - High Temperature (0.8 to 1.2): Highly creative and random (good for brainstorming/stories).\n// - Low Temperature (default 0.2): Focused and consistent, but minor variations can still occur.\n// - Zero Temperature (0.0): Completely deterministic. The model will select the highest-probability\n//   word at every step, guaranteeing the exact same output every run.", "jason/acceptance-patterns/pattern-4-cross-llm-verification/src/main/asl/main.asl": "// Pipeline: start > !banner > !classified > !verified > !cross_check > !evaluate_verifier > !match_labels | !rejected_verifier | !rejected_primary\n/**\n * Pattern 4: Cross-LLM Verification - Jason\n *\n * Use a primary provider and a verifier provider; accept only\n * when both candidates agree.\n */\n\n// Requires: GL ontology beliefs (gl_status, gl_candidate_type, gl_verdict_type, ...)\n//   See: https://github.com/generativelayers/examples/tree/main/jason/shared\n\n// DOMAIN MODEL\nverified(Cid) :- accepted(Cid).\nverified(Cid) :- rejected(Cid).\nhas_candidate(Cid) :- Cid \\== \"\".\nno_candidate(Cid)  :- Cid == \"\".\n\n!start.\n\n// DECOMPOSITION: start only adopts subgoals\n+!start\n   <- !banner;\n      gl.bind(\"agent1\", \"groq\", \"openai/gpt-oss-120b\", \"\", Bid);\n      +primary_binding(Bid);\n      gl.bind(\"verifier1\", \"cerebras\", \"gpt-oss-120b\", \"\", Vbid);\n      +verifier_binding(Vbid);\n      !classified(\"apple\");\n      !shutdown.\n\n// ACHIEVEMENT: clean exit\n+!shutdown\n   <- .stopMAS.\n\n// ACHIEVEMENT: display banner\n+!banner\n   :  gl.see(Providers)\n   <- .println(\"=== Pattern 4: Cross-LLM Verification ===\");\n      .println(\"\");\n      .println(\"[Layer] Available providers: \", Providers).\n\n// DECOMPOSITION: classify = call + deliberate/verify\n+!classified(Item)\n   :  primary_binding(Bid) & verifier_binding(Vbid)\n   <- .concat(\"Classify: \", Item, \". Return only a label field.\", Prompt);\n      gl.call(Bid, \"classify\", \"llm.answer\", \"ANSWER\", Prompt, \"label\", \"\", Rid);\n      !verified(Rid, Item, Bid, Vbid).\n\n// SERENDIPITY: already verified\n+!verified(Rid, Item, Bid, Vbid)\n   :  gl.candidate(Rid, Cid) & verified(Cid)\n   <- .println(\"[AGENT] Already verified: \", Rid).\n\n// DECOMPOSITION: admissible > check verifier output\n+!verified(Rid, Item, Bid, Vbid)\n   :  gl.candidate(Rid, Cid) & gl.decide(Cid, \"ADMISSIBLE\") & gl.get(Cid, \"label\", Label)\n   <- !cross_check(Rid, Cid, Label, Item, Bid, Vbid).\n\n// DECOMPOSITION: not admissible > reject\n+!verified(Rid, Item, Bid, Vbid)\n   :  gl.candidate(Rid, Cid)\n   <- !rejected_primary(Cid, Rid).\n\n// DECOMPOSITION: cross-check with verifier\n+!cross_check(Rid, PrimaryCid, PrimaryLabel, Item, Bid, Vbid)\n   <- .concat(\"Classify this item and return only a label field: \", Item, Prompt);\n      gl.call(Vbid, \"verify\", \"llm.answer\", \"ANSWER\", Prompt, \"label\", \"\", Vrid);\n      !evaluate_verifier(Rid, PrimaryCid, PrimaryLabel, Vrid, Item).\n\n// DECOMPOSITION: verifier admissible > compare labels\n+!evaluate_verifier(Rid, PrimaryCid, PrimaryLabel, Vrid, Item)\n   :  gl.candidate(Vrid, VerifierCid) & gl.decide(VerifierCid, \"ADMISSIBLE\") & gl.get(VerifierCid, \"label\", VerifierLabel)\n   <- .println(\"Primary Agent: label = \", PrimaryLabel);\n      .println(\"Verifier Agent: label = \", VerifierLabel);\n      !match_labels(Rid, PrimaryCid, PrimaryLabel, Vrid, VerifierCid, VerifierLabel).\n\n// DECOMPOSITION: verifier not admissible > reject\n+!evaluate_verifier(Rid, PrimaryCid, PrimaryLabel, Vrid, Item)\n   :  gl.candidate(Vrid, VerifierCid)\n   <- !rejected_verifier(PrimaryCid, VerifierCid, Rid, Vrid).\n\n// ACHIEVEMENT: labels match > accept both\n+!match_labels(Rid, PrimaryCid, PrimaryLabel, Vrid, VerifierCid, VerifierLabel)\n   :  PrimaryLabel == VerifierLabel\n   <- .concat(\"cross-LLM match: \", PrimaryLabel, Reason1);\n      .concat(\"cross-LLM match: \", VerifierLabel, Reason2);\n      gl.accept(PrimaryCid, Reason1, _);\n      gl.accept(VerifierCid, Reason2, _);\n      +accepted(PrimaryCid);\n      +accepted(VerifierCid);\n      .println(\"Result: MATCH - ACCEPTED\");\n      !print_trace(Rid);\n      !print_trace(Vrid);\n      .println(\"=== Demo Complete ===\").\n\n// ACHIEVEMENT: labels mismatch > reject both\n+!match_labels(Rid, PrimaryCid, PrimaryLabel, Vrid, VerifierCid, VerifierLabel)\n   :  PrimaryLabel \\== VerifierLabel\n   <- .concat(\"cross-LLM mismatch: \", PrimaryLabel, \" vs \", VerifierLabel, Reason);\n      gl.reject(PrimaryCid, Reason, _);\n      gl.reject(VerifierCid, Reason, _);\n      +rejected(PrimaryCid);\n      +rejected(VerifierCid);\n      .println(\"Result: MISMATCH - REJECTED\");\n      !print_trace(Rid);\n      !print_trace(Vrid);\n      .println(\"=== Demo Complete ===\").\n\n// ACHIEVEMENT: reject primary (candidate exists)\n+!rejected_primary(Cid, Rid)\n   :  has_candidate(Cid)\n   <- gl.reject(Cid, \"primary validation failed\", _);\n      +rejected(Cid);\n      .println(\"Invalid primary output - REJECTED\");\n      !print_trace(Rid).\n\n// ACHIEVEMENT: reject primary (no candidate)\n+!rejected_primary(Cid, Rid)\n   :  no_candidate(Cid)\n   <- +rejected(\"\");\n      .println(\"Primary invocation failed - REJECTED\");\n      !print_trace(Rid).\n\n// DECOMPOSITION: reject verifier\n+!rejected_verifier(PrimaryCid, VerifierCid, Rid, Vrid)\n   <- !reject_single_cid(PrimaryCid);\n      !reject_single_cid(VerifierCid);\n      .println(\"Verifier output invalid - REJECTED\");\n      !print_trace(Rid);\n      !print_trace(Vrid).\n\n// ACHIEVEMENT: reject single candidate (exists)\n+!reject_single_cid(Cid)\n   :  has_candidate(Cid)\n   <- gl.reject(Cid, \"verifier validation failed\", _);\n      +rejected(Cid).\n\n// ACHIEVEMENT: reject single candidate (none)\n+!reject_single_cid(Cid)\n   :  no_candidate(Cid)\n   <- +rejected(\"\").\n\n// ACHIEVEMENT: print trace\n+!print_trace(Rid)\n   :  gl.explain(Rid, Trace)\n   <- .println(\"\");\n      .println(\"[TRACE] \", Trace).\n\n// RECOVERY\n-!verified(Rid, Item, Bid, Vbid)\n   :  not accepted(_) & not rejected(_)\n   <- .println(\"Verification FAILED for \", Rid).\n\n// NOTE: To make verification deterministic, you can configure the temperature parameter.\n// Pass \"temperature=0.0\" inside the configuration string (4th argument of the bind call):\n//\n// gl.bind(\"agent1\", \"groq\", \"openai/gpt-oss-120b\", \"temperature=0.0\", Bid);\n// gl.bind(\"verifier1\", \"cerebras\", \"gpt-oss-120b\", \"temperature=0.0\", Vbid);\n//\n// Temperature levels control model randomness:\n// - High Temperature (0.8 to 1.2): Highly creative and random (good for brainstorming/stories).\n// - Low Temperature (default 0.2): Focused and consistent, but minor variations can still occur.\n// - Zero Temperature (0.0): Completely deterministic. The model will select the highest-probability\n//   word at every step, guaranteeing the exact same output every run.", "jacamo/acceptance-patterns/pattern-4-cross-llm-verification/src/agt/main.asl": "// Pipeline: start > !banner > !setup > !classified > !verified > !cross_check > !evaluate_verifier > !match_labels | !rejected_verifier | !rejected_primary\n/**\n * Pattern 4: Cross-LLM Verification - JaCaMo\n *\n * Use a primary provider and a verifier provider; accept only\n * when both candidates agree.\n */\n\n// DOMAIN MODEL\nverified(Cid) :- accepted(Cid).\nverified(Cid) :- rejected(Cid).\nhas_candidate(Cid) :- Cid \\== \"\".\nno_candidate(Cid)  :- Cid == \"\".\n\n!start.\n\n// DECOMPOSITION: start only adopts subgoals\n+!start\n   <- !artifact_ready;\n      !banner;\n      !setup;\n      !classified(\"apple\");\n      .stopMAS.\n\n// ACHIEVEMENT: create and focus the GL artifact\n+!artifact_ready\n   <- makeArtifact(\"gl\", \"gl.jacamo.GL\", [], GlId);\n      focus(GlId).\n\n// ACHIEVEMENT: display banner\n+!banner\n   <- see(Providers);\n      .println(\"=== Pattern 4: Cross-LLM Verification ===\");\n      .println(\"\").\n\n// ACHIEVEMENT: setup\n+!setup\n   <- bind(\"agent1\", \"groq\", \"openai/gpt-oss-120b\", \"\", Bid);\n      +primary_binding(Bid);\n      bind(\"verifier1\", \"cerebras\", \"gpt-oss-120b\", \"\", Vbid);\n      +verifier_binding(Vbid).\n\n// DECOMPOSITION: classify = call + deliberate/verify\n+!classified(Item)\n   :  primary_binding(Bid) & verifier_binding(Vbid)\n   <- .concat(\"Classify: \", Item, \". Return only a label field.\", Prompt);\n      call(Bid, \"classify\", \"llm.answer\", \"ANSWER\", Prompt, \"label\", \"\", Rid);\n      !verified(Rid, Item, Bid, Vbid).\n\n// SERENDIPITY: already verified\n+!verified(Rid, Item, Bid, Vbid)\n   :  accepted(Cid) & candidate(Rid, Cid)\n   <- .println(\"Already verified: \", Rid).\n\n// DECOMPOSITION: handle deliberation\n+!verified(Rid, Item, Bid, Vbid)\n   <- candidate(Rid, Cid);\n      !verified_candidate(Rid, Cid, Item, Bid, Vbid).\n\n+!verified_candidate(Rid, Cid, Item, Bid, Vbid)\n   :  has_candidate(Cid)\n   <- decide(Cid, Admissibility);\n      !verified_decision(Rid, Cid, Admissibility, Item, Bid, Vbid).\n\n+!verified_candidate(Rid, Cid, Item, Bid, Vbid)\n   :  no_candidate(Cid)\n   <- result(Rid, Outcome);\n      !verified_decision(Rid, Cid, Outcome, Item, Bid, Vbid).\n\n// DECOMPOSITION: route primary decision\n+!verified_decision(Rid, Cid, \"ADMISSIBLE\", Item, Bid, Vbid)\n   <- get(Cid, \"label\", Label);\n      !cross_check(Rid, Cid, Label, Item, Bid, Vbid).\n\n+!verified_decision(Rid, Cid, Outcome, Item, Bid, Vbid)\n   <- !rejected_primary(Cid, Rid, Outcome).\n\n// DECOMPOSITION: cross-check with verifier\n+!cross_check(Rid, PrimaryCid, PrimaryLabel, Item, Bid, Vbid)\n   <- .concat(\"Classify this item and return only a label field: \", Item, Prompt);\n      call(Vbid, \"verify\", \"llm.answer\", \"ANSWER\", Prompt, \"label\", \"\", Vrid);\n      !evaluate_verifier(Rid, PrimaryCid, PrimaryLabel, Vrid, Item).\n\n// DECOMPOSITION: evaluate verifier\n+!evaluate_verifier(Rid, PrimaryCid, PrimaryLabel, Vrid, Item)\n   <- candidate(Vrid, VerifierCid);\n      !evaluate_verifier_candidate(Rid, PrimaryCid, PrimaryLabel, Vrid, VerifierCid, Item).\n\n+!evaluate_verifier_candidate(Rid, PrimaryCid, PrimaryLabel, Vrid, VerifierCid, Item)\n   :  has_candidate(VerifierCid)\n   <- decide(VerifierCid, Admissibility);\n      !evaluate_verifier_decision(Rid, PrimaryCid, PrimaryLabel, Vrid, VerifierCid, Admissibility, Item).\n\n+!evaluate_verifier_candidate(Rid, PrimaryCid, PrimaryLabel, Vrid, VerifierCid, Item)\n   :  no_candidate(VerifierCid)\n   <- result(Vrid, Outcome);\n      !evaluate_verifier_decision(Rid, PrimaryCid, PrimaryLabel, Vrid, VerifierCid, Outcome, Item).\n\n// DECOMPOSITION: route verifier decision\n+!evaluate_verifier_decision(Rid, PrimaryCid, PrimaryLabel, Vrid, VerifierCid, \"ADMISSIBLE\", Item)\n   <- get(VerifierCid, \"label\", VerifierLabel);\n      .println(\"Primary Agent: label = \", PrimaryLabel);\n      .println(\"Verifier Agent: label = \", VerifierLabel);\n      !match_labels(Rid, PrimaryCid, PrimaryLabel, Vrid, VerifierCid, VerifierLabel).\n\n+!evaluate_verifier_decision(Rid, PrimaryCid, PrimaryLabel, Vrid, VerifierCid, Outcome, Item)\n   <- !rejected_verifier(PrimaryCid, VerifierCid, Rid, Vrid, Outcome).\n\n// ACHIEVEMENT: labels match > accept both\n+!match_labels(Rid, PrimaryCid, PrimaryLabel, Vrid, VerifierCid, VerifierLabel)\n   :  PrimaryLabel == VerifierLabel\n   <- .concat(\"cross-LLM match: \", PrimaryLabel, Reason1);\n      .concat(\"cross-LLM match: \", VerifierLabel, Reason2);\n      accept(PrimaryCid, Reason1, _);\n      accept(VerifierCid, Reason2, _);\n      +accepted(PrimaryCid);\n      +accepted(VerifierCid);\n      .println(\"Result: MATCH - ACCEPTED\");\n      !print_trace(Rid);\n      !print_trace(Vrid);\n      .println(\"=== Demo Complete ===\").\n\n// ACHIEVEMENT: labels mismatch > reject both\n+!match_labels(Rid, PrimaryCid, PrimaryLabel, Vrid, VerifierCid, VerifierLabel)\n   :  PrimaryLabel \\== VerifierLabel\n   <- .concat(\"cross-LLM mismatch: \", PrimaryLabel, \" vs \", VerifierLabel, Reason);\n      reject(PrimaryCid, Reason, _);\n      reject(VerifierCid, Reason, _);\n      +rejected(PrimaryCid);\n      +rejected(VerifierCid);\n      .println(\"Result: MISMATCH - REJECTED\");\n      !print_trace(Rid);\n      !print_trace(Vrid);\n      .println(\"=== Demo Complete ===\").\n\n// ACHIEVEMENT: reject primary (candidate exists)\n+!rejected_primary(Cid, Rid, Outcome)\n   :  has_candidate(Cid)\n   <- reject(Cid, \"primary validation failed\", _);\n      +rejected(Cid);\n      .println(\"Invalid primary output - REJECTED\");\n      !print_trace(Rid).\n\n// ACHIEVEMENT: reject primary (no candidate)\n+!rejected_primary(Cid, Rid, Outcome)\n   :  no_candidate(Cid)\n   <- +rejected(\"\");\n      .println(\"Primary invocation failed - REJECTED\");\n      !print_trace(Rid).\n\n// DECOMPOSITION: reject verifier\n+!rejected_verifier(PrimaryCid, VerifierCid, Rid, Vrid, Outcome)\n   <- !reject_single_cid(PrimaryCid);\n      !reject_single_cid(VerifierCid);\n      .println(\"Verifier output invalid - REJECTED (outcome = \", Outcome, \")\");\n      !print_trace(Rid);\n      !print_trace(Vrid).\n\n// ACHIEVEMENT: reject single candidate (exists)\n+!reject_single_cid(Cid)\n   :  has_candidate(Cid)\n   <- reject(Cid, \"verifier validation failed\", _);\n      +rejected(Cid).\n\n// ACHIEVEMENT: reject single candidate (none)\n+!reject_single_cid(Cid)\n   :  no_candidate(Cid)\n   <- +rejected(\"\").\n\n// ACHIEVEMENT: print trace\n+!print_trace(Rid)\n   <- explain(Rid, Trace);\n      .println(\"\");\n      .println(\"[TRACE] \", Trace).\n\n// RECOVERY\n-!verified(Rid, Item, Bid, Vbid)\n   :  not accepted(_) & not rejected(_)\n   <- .println(\"Verification FAILED for \", Rid).\n\n// NOTE: To make verification deterministic, you can configure the temperature parameter.\n// Pass \"temperature=0.0\" inside the configuration string (4th argument of the bind call):\n//\n// bind(\"agent1\", \"groq\", \"openai/gpt-oss-120b\", \"temperature=0.0\", Bid);\n// bind(\"verifier1\", \"cerebras\", \"gpt-oss-120b\", \"temperature=0.0\", Vbid);\n//\n// Temperature levels control model randomness:\n// - High Temperature (0.8 to 1.2): Highly creative and random (good for brainstorming/stories).\n// - Low Temperature (default 0.2): Focused and consistent, but minor variations can still occur.\n// - Zero Temperature (0.0): Completely deterministic. The model will select the highest-probability\n//   word at every step, guaranteeing the exact same output every run.", "astra/acceptance-patterns/pattern-5-agent-to-agent-review/src/main/astra/Main.astra": "/**\n * Pattern 5: Agent-to-Agent Review - ASTRA (Launcher)\n *\n * Creates the reviewer and runner agents.\n */\nagent Main {\n    module Console console;\n    module System S;\n\n    rule +!main(list args) {\n        console.println(\"=== Pattern 5: Agent-to-Agent Review ===\");\n        console.println(\"\");\n        S.createAgent(\"reviewer\", \"Reviewer\");\n        S.createAgent(\"runner\", \"PatternRunner\");\n    }\n}", "astra/acceptance-patterns/pattern-5-agent-to-agent-review/src/main/astra/PatternRunner.astra": "// Pipeline: start > !classified > !reviewed > !submit_for_review > send(reviewer) > wait > ?reviewed\n// Pattern 5: Agent-to-Agent Review - ASTRA\n//\n// A generating agent asks a reviewer agent before accepting\n// the candidate.\nagent PatternRunner {\n    module gl.astra.GL gl;\n    module Console console;\n    module System S;\n\n    types review_types {\n        formula binding(string);\n        formula reviewed(string);\n        formula peer_approved(string);\n        formula peer_rejected(string);\n        formula review_request(string, string);\n        formula review_approved(string);\n        formula review_rejected(string, string);\n    }\n\n    // Sub-agents use initial !start() (not +!main)\n    initial !start();\n\n    // DOMAIN MODEL\n    inference reviewed(string cid) :- peer_approved(cid);\n    inference reviewed(string cid) :- peer_rejected(cid);\n\n    // DECOMPOSITION: start > configure > review\n    rule +!start() {\n        console.println(\"[Layer] Available providers: \" + gl.see());\n        +binding(gl.bind(\"agent1\", \"groq\", \"openai/gpt-oss-120b\", \"\"));\n        !classified(\"tomato\");\n        !shutdown();\n    }\n\n    // ACHIEVEMENT: clean exit\n    rule +!shutdown() {\n        S.exit();\n    }\n\n    // DECOMPOSITION: classify = call + deliberate\n    rule +!classified(string item) : binding(string bid) {\n        !reviewed(gl.call(bid, \"classify\", \"llm.answer\", \"ANSWER\",\n            \"Classify: \" + item + \". Return only a label field.\", \"label\", \"\"));\n    }\n\n    // SERENDIPITY: already reviewed\n    rule +!reviewed(string rid) : reviewed(gl.candidate(rid)) {\n        console.println(\"[Runner] Already reviewed: \" + rid);\n    }\n\n    // DECOMPOSITION: admissible > send to reviewer and wait\n    rule +!reviewed(string rid) : gl.decide(gl.candidate(rid)) == \"ADMISSIBLE\" {\n        !submit_for_review(rid, gl.candidate(rid), gl.get(gl.candidate(rid), \"label\"));\n    }\n\n    // DECOMPOSITION: invalid output > reject\n    rule +!reviewed(string rid) {\n        !rejected_candidate(gl.candidate(rid), rid);\n    }\n\n    // ACHIEVEMENT: submit for review (actions only)\n    rule +!submit_for_review(string rid, string cid, string label) {\n        console.println(\"[Runner] Sending '\" + label + \"' to reviewer...\");\n        send(request, \"reviewer\", review_request(label, cid));\n        // Wait for peer verdict via belief event (30s timeout)\n        wait(peer_approved(cid), 30000);\n    }\n\n    // ACHIEVEMENT: reject (actions only)\n    rule +!rejected_candidate(string cid, string rid) {\n        gl.reject(cid, \"failed validation\");\n        +peer_rejected(cid);\n        console.println(\"Invalid output - REJECTED\");\n        !print_trace(rid);\n    }\n\n    // REACTIVE: peer approved > record peer approval and GL adoption decision\n    rule @message(inform, string sender, review_approved(string cid)) {\n        +peer_approved(cid);\n        gl.accept(cid, \"peer approved\");\n        console.println(\"[Runner] Peer approved - ACCEPTED\");\n        console.println(\"\");\n        console.println(\"[TRACE] \" + gl.explain(cid));\n        console.println(\"=== Demo Complete ===\");\n    }\n\n    // REACTIVE: peer rejected > reject\n    rule @message(inform, string sender, review_rejected(string cid, string reason)) {\n        +peer_rejected(cid);\n        gl.reject(cid, \"peer rejected: \" + reason);\n        console.println(\"[Runner] Peer rejected: \" + reason + \" - REJECTED\");\n        console.println(\"\");\n        console.println(\"[TRACE] \" + gl.explain(cid));\n        console.println(\"=== Demo Complete ===\");\n    }\n\n    // ACHIEVEMENT: print trace\n    rule +!print_trace(string rid) {\n        console.println(\"\");\n        console.println(\"[TRACE] \" + gl.explain(rid));\n    }\n\n    // RECOVERY\n    rule -!reviewed(string rid) : ~peer_approved(string _) & ~peer_rejected(string _) {\n        console.println(\"[Runner] Review FAILED for \" + rid);\n    }\n}", "astra/acceptance-patterns/pattern-5-agent-to-agent-review/src/main/astra/Reviewer.astra": "// Pipeline: @message > +review_pending > !review_decided > send(approve|reject)\nagent Reviewer {\n    module Console console;\n\n    types review_types {\n        formula review_request(string, string);\n        formula review_approved(string);\n        formula review_rejected(string, string);\n        formula review_pending(string, string, string);\n        formula review_decided(string);\n        formula known_food(string);\n    }\n\n    initial known_food(\"fruit\"), known_food(\"vegetable\"), known_food(\"grain\"),\n           known_food(\"dairy\"), known_food(\"protein\"), known_food(\"food\");\n\n    // DOMAIN MODEL\n    inference review_decided(string cid) :- review_approved(cid);\n\n    // REACTIVE: incoming request > store as belief\n    rule @message(request, string sender, review_request(string label, string cid)) {\n        console.println(\"[Reviewer] Received review request: label='\" + label + \"', cid=\" + cid);\n        +review_pending(label, cid, sender);\n    }\n\n    // DELIBERATION: pending review > adopt decision goal\n    rule +review_pending(string label, string cid, string sender) : ~review_decided(cid) {\n        !review_decided(cid);\n    }\n\n    // SERENDIPITY\n    rule +!review_decided(string cid) : review_decided(cid) {\n        console.println(\"[Reviewer] Already decided for \" + cid);\n    }\n\n    // ACHIEVEMENT: known > approve\n    rule +!review_decided(string cid) : review_pending(string label, cid, string sender) & known_food(label) {\n        send(inform, sender, review_approved(cid));\n        +review_approved(cid);\n        console.println(\"[Reviewer] '\" + label + \"' is known > APPROVED\");\n    }\n\n    // ACHIEVEMENT: unknown > reject\n    rule +!review_decided(string cid) : review_pending(string label, cid, string sender) & ~known_food(label) {\n        send(inform, sender, review_rejected(cid, \"not in knowledge base\"));\n        console.println(\"[Reviewer] '\" + label + \"' is unknown > DISAPPROVED\");\n    }\n\n    // RECOVERY: only fire when no decision was actually made\n    rule -!review_decided(string cid) : ~review_approved(cid) {\n        console.println(\"[Reviewer] Decision FAILED for \" + cid);\n    }\n}", "jason/acceptance-patterns/pattern-5-agent-to-agent-review/src/main/asl/main.asl": "// Pipeline: start > !banner > !setup > !classified > !reviewed > !submit_for_review > .wait(reviewed) > +review_approved | +review_rejected\n/**\n * Pattern 5: Agent-to-Agent Review - Jason (Main agent)\n *\n * Generates LLM output, sends the label to a peer reviewer\n * agent via messaging. Accepts/rejects based on reviewer's verdict.\n */\n\n// Requires: GL ontology beliefs (gl_status, gl_candidate_type, gl_verdict_type, ...)\n//   See: https://github.com/generativelayers/examples/tree/main/jason/shared\n\n// DOMAIN MODEL\nreviewed(Cid) :- peer_approved(Cid).\nreviewed(Cid) :- peer_rejected(Cid).\nhas_candidate(Cid) :- Cid \\== \"\".\nno_candidate(Cid)  :- Cid == \"\".\n\n!start.\n\n// DECOMPOSITION: start only adopts subgoals\n+!start\n   <- !banner;\n      !setup;\n      !classified(\"tomato\");\n      !shutdown.\n\n// ACHIEVEMENT: setup binding\n+!setup\n   <- gl.bind(\"agent1\", \"groq\", \"openai/gpt-oss-120b\", \"\", Bid);\n      +binding(Bid);\n      ?binding(Bid).\n\n// ACHIEVEMENT: clean exit\n+!shutdown\n   <- .stopMAS.\n\n// ACHIEVEMENT: display banner\n+!banner\n   :  gl.see(Providers)\n   <- .println(\"=== Pattern 5: Agent-to-Agent Review ===\");\n      .println(\"\");\n      .println(\"[Layer] Available providers: \", Providers).\n\n// DECOMPOSITION: classify = call + review\n+!classified(Item)\n   :  binding(Bid)\n   <- .concat(\"Classify: \", Item, \". Return only a label field.\", Prompt);\n      gl.call(Bid, \"classify\", \"llm.answer\", \"ANSWER\", Prompt, \"label\", \"\", Rid);\n      !reviewed(Rid).\n\n// SERENDIPITY: already reviewed\n+!reviewed(Rid)\n   :  gl.candidate(Rid, Cid) & reviewed(Cid)\n   <- .println(\"[Runner] Already reviewed: \", Rid).\n\n// DECOMPOSITION: admissible > send to reviewer and wait\n+!reviewed(Rid)\n   :  gl.candidate(Rid, Cid) & gl.decide(Cid, \"ADMISSIBLE\") & gl.get(Cid, \"label\", Label)\n   <- !submit_for_review(Rid, Cid, Label);\n      .wait(reviewed(Cid), 30000).\n\n// DECOMPOSITION: not admissible > reject\n+!reviewed(Rid)\n   :  gl.candidate(Rid, Cid)\n   <- !rejected_candidate(Cid, Rid).\n\n// ACHIEVEMENT: send request to reviewer\n+!submit_for_review(Rid, Cid, Label)\n   <- .println(\"[Runner] Sending '\", Label, \"' to reviewer...\");\n      .send(reviewer, achieve, review_request(Label, Cid)).\n\n// ACHIEVEMENT: reject primary (candidate exists)\n+!rejected_candidate(Cid, Rid)\n   :  has_candidate(Cid)\n   <- gl.reject(Cid, \"failed validation\", _);\n      +peer_rejected(Cid);\n      .println(\"Invalid output - REJECTED\");\n      !print_trace(Rid).\n\n// ACHIEVEMENT: reject primary (no candidate)\n+!rejected_candidate(Cid, Rid)\n   :  no_candidate(Cid)\n   <- +peer_rejected(\"\");\n      .println(\"Invocation failed - REJECTED\");\n      !print_trace(Rid).\n\n// REACTIVE: peer approved\n+review_approved(Cid)[source(Sender)]\n   <- +peer_approved(Cid);\n      gl.accept(Cid, \"peer approved\", _);\n      .println(\"[Runner] Peer approved - ACCEPTED\");\n      .println(\"\");\n      gl.explain(Cid, Trace);\n      .println(\"[TRACE] \", Trace);\n      .println(\"=== Demo Complete ===\").\n\n// REACTIVE: peer rejected\n+review_rejected(Cid, Reason)[source(Sender)]\n   <- +peer_rejected(Cid);\n      gl.reject(Cid, Reason, _);\n      .println(\"[Runner] Peer rejected: \", Reason, \" - REJECTED\");\n      .println(\"\");\n      gl.explain(Cid, Trace);\n      .println(\"[TRACE] \", Trace);\n      .println(\"=== Demo Complete ===\").\n\n// ACHIEVEMENT: print trace\n+!print_trace(Rid)\n   :  gl.explain(Rid, Trace)\n   <- .println(\"\");\n      .println(\"[TRACE] \", Trace).\n\n// RECOVERY - candidate exists\n-!reviewed(Rid)\n   :  gl.candidate(Rid, Cid) & has_candidate(Cid)\n   <- .println(\"[Runner] Review TIMED OUT or FAILED > REJECTED\");\n      gl.reject(Cid, \"review timed out/failed\", _);\n      +peer_rejected(Cid);\n      !print_trace(Rid).\n\n// RECOVERY - no candidate\n-!reviewed(Rid)\n   <- .println(\"[Runner] Review FAILED for \", Rid).", "jason/acceptance-patterns/pattern-5-agent-to-agent-review/src/main/asl/reviewer.asl": "// Pipeline: +!review_request > !review_decided > .send(approve|reject) > ?review_decided\n/**\n * Pattern 5: Agent-to-Agent Review - Jason (Reviewer)\n *\n * Pure BDI reviewer - no LLM involved.\n * Checks the label against its own beliefs and responds.\n */\n\n// Requires: GL ontology beliefs (gl_status, gl_candidate_type, gl_verdict_type, ...)\n//   See: https://github.com/generativelayers/examples/tree/main/jason/shared\n\nknown_food(\"fruit\"). known_food(\"vegetable\"). known_food(\"grain\").\nknown_food(\"dairy\"). known_food(\"protein\"). known_food(\"food\").\n\n// DOMAIN MODEL\nreview_decided(Cid) :- review_approved(Cid).\nreview_decided(Cid) :- review_rejected(Cid).\n\n// ACHIEVEMENT: incoming request > store and deliberate\n+!review_request(Label, Cid)\n   <- +review_pending(Label, Cid);\n      !review_decided(Cid).\n\n// SERENDIPITY\n+!review_decided(Cid)\n   :  review_decided(Cid)\n   <- .println(\"[Reviewer] Already decided for \", Cid).\n\n// ACHIEVEMENT: known > approve\n+!review_decided(Cid)\n   :  review_pending(Label, Cid) & known_food(Label)\n   <- .send(main, tell, review_approved(Cid));\n      +review_approved(Cid);\n      ?review_decided(Cid);\n      .println(\"[Reviewer] '\", Label, \"' is known > APPROVED\").\n\n// ACHIEVEMENT: unknown > reject\n+!review_decided(Cid)\n   :  review_pending(Label, Cid) & not known_food(Label)\n   <- .send(main, tell, review_rejected(Cid, \"not in knowledge base\"));\n      +review_rejected(Cid);\n      ?review_decided(Cid);\n      .println(\"[Reviewer] '\", Label, \"' is unknown > DISAPPROVED\").\n\n// RECOVERY\n-!review_decided(Cid)\n   <- .println(\"[Reviewer] Decision FAILED for \", Cid).", "jacamo/acceptance-patterns/pattern-5-agent-to-agent-review/src/agt/main.asl": "// Pipeline: start > !banner > !setup > !classified > !reviewed > !submit_for_review > .wait(reviewed) > +review_approved | +review_rejected\n/**\n * Pattern 5: Agent-to-Agent Review - JaCaMo (Main agent)\n *\n * Generates LLM output, sends the label to a peer reviewer\n * agent via messaging. Accepts/rejects based on reviewer's verdict.\n */\n\n// DOMAIN MODEL\nreviewed(Cid) :- peer_approved(Cid).\nreviewed(Cid) :- peer_rejected(Cid).\nhas_candidate(Cid) :- Cid \\== \"\".\nno_candidate(Cid)  :- Cid == \"\".\n\n!start.\n\n// DECOMPOSITION: start only adopts subgoals\n+!start\n   <- !artifact_ready;\n      !banner;\n      !setup;\n      !classified(\"tomato\");\n      .stopMAS.\n\n// ACHIEVEMENT: create and focus the GL artifact\n+!artifact_ready\n   <- makeArtifact(\"gl\", \"gl.jacamo.GL\", [], GlId);\n      focus(GlId).\n\n// ACHIEVEMENT: display banner\n+!banner\n   <- see(Providers);\n      .println(\"=== Pattern 5: Agent-to-Agent Review ===\");\n      .println(\"\").\n\n// ACHIEVEMENT: setup\n+!setup\n   <- bind(\"agent1\", \"groq\", \"openai/gpt-oss-120b\", \"\", Bid);\n      +binding(Bid).\n\n// DECOMPOSITION: classify = call + review\n+!classified(Item)\n   :  binding(Bid)\n   <- .concat(\"Classify: \", Item, \". Return only a label field.\", Prompt);\n      call(Bid, \"classify\", \"llm.answer\", \"ANSWER\", Prompt, \"label\", \"\", Rid);\n      !reviewed(Rid).\n\n// SERENDIPITY: already reviewed\n+!reviewed(Rid)\n   :  accepted(Cid) & candidate(Rid, Cid)\n   <- .println(\"[Runner] Already reviewed: \", Rid).\n\n// DECOMPOSITION: handle deliberation\n+!reviewed(Rid)\n   <- candidate(Rid, Cid);\n      !reviewed_candidate(Rid, Cid).\n\n+!reviewed_candidate(Rid, Cid)\n   :  has_candidate(Cid)\n   <- decide(Cid, Admissibility);\n      !reviewed_decision(Rid, Cid, Admissibility).\n\n+!reviewed_candidate(Rid, Cid)\n   :  no_candidate(Cid)\n   <- result(Rid, Outcome);\n      !reviewed_decision(Rid, Cid, Outcome).\n\n// DECOMPOSITION: route decision\n+!reviewed_decision(Rid, Cid, \"ADMISSIBLE\")\n   <- get(Cid, \"label\", Label);\n      !submit_for_review(Rid, Cid, Label);\n      .wait(reviewed(Cid), 30000).\n\n+!reviewed_decision(Rid, Cid, Outcome)\n   <- !rejected_candidate(Cid, Rid, Outcome).\n\n// ACHIEVEMENT: send request to reviewer\n+!submit_for_review(Rid, Cid, Label)\n   <- .println(\"[Runner] Sending '\", Label, \"' to reviewer...\");\n      .send(reviewer, achieve, review_request(Label, Cid)).\n\n// ACHIEVEMENT: reject primary (candidate exists)\n+!rejected_candidate(Cid, Rid, Outcome)\n   :  has_candidate(Cid)\n   <- reject(Cid, \"failed validation\", _);\n      +peer_rejected(Cid);\n      .println(\"Invalid output - REJECTED\");\n      !print_trace(Rid).\n\n// ACHIEVEMENT: reject primary (no candidate)\n+!rejected_candidate(Cid, Rid, Outcome)\n   :  no_candidate(Cid)\n   <- +peer_rejected(\"\");\n      .println(\"Invocation failed - REJECTED\");\n      !print_trace(Rid).\n\n// REACTIVE: peer approved\n+review_approved(Cid)[source(Sender)]\n   <- +peer_approved(Cid);\n      accept(Cid, \"peer approved\", _);\n      .println(\"[Runner] Peer approved - ACCEPTED\");\n      .println(\"\");\n      explain(Cid, Trace);\n      .println(\"[TRACE] \", Trace);\n      .println(\"=== Demo Complete ===\").\n\n// REACTIVE: peer rejected\n+review_rejected(Cid, Reason)[source(Sender)]\n   <- +peer_rejected(Cid);\n      reject(Cid, Reason, _);\n      .println(\"[Runner] Peer rejected: \", Reason, \" - REJECTED\");\n      .println(\"\");\n      explain(Cid, Trace);\n      .println(\"[TRACE] \", Trace);\n      .println(\"=== Demo Complete ===\").\n\n// ACHIEVEMENT: print trace\n+!print_trace(Rid)\n   <- explain(Rid, Trace);\n      .println(\"\");\n      .println(\"[TRACE] \", Trace).\n\n// RECOVERY - candidate exists (timed out or failed)\n-!reviewed(Rid)\n   :  candidate(Rid, Cid) & has_candidate(Cid)\n   <- .println(\"[Runner] Review TIMED OUT or FAILED > REJECTED\");\n      reject(Cid, \"review timed out/failed\", _);\n      +peer_rejected(Cid);\n      !print_trace(Rid).\n\n// RECOVERY - no candidate\n-!reviewed(Rid)\n   <- .println(\"[Runner] Review FAILED for \", Rid).", "jacamo/acceptance-patterns/pattern-5-agent-to-agent-review/src/agt/reviewer.asl": "// Pipeline: +!review_request > !review_decided > .send(approve|reject) > ?review_decided\n/**\n * Pattern 5: Agent-to-Agent Review - JaCaMo (Reviewer)\n *\n * Pure BDI reviewer - no LLM involved.\n * Checks the label against its own beliefs and responds.\n */\n\nknown_food(\"fruit\"). known_food(\"vegetable\"). known_food(\"grain\").\nknown_food(\"dairy\"). known_food(\"protein\"). known_food(\"food\").\n\n// DOMAIN MODEL\nreview_decided(Cid) :- review_approved(Cid).\nreview_decided(Cid) :- review_rejected(Cid).\n\n// ACHIEVEMENT: incoming request > store and deliberate\n+!review_request(Label, Cid)\n   <- +review_pending(Label, Cid);\n      !review_decided(Cid).\n\n// SERENDIPITY\n+!review_decided(Cid)\n   :  review_decided(Cid)\n   <- .println(\"[Reviewer] Already decided for \", Cid).\n\n// ACHIEVEMENT: known > approve\n+!review_decided(Cid)\n   :  review_pending(Label, Cid) & known_food(Label)\n   <- .send(main, tell, review_approved(Cid));\n      +review_approved(Cid);\n      ?review_decided(Cid);\n      .println(\"[Reviewer] '\", Label, \"' is known > APPROVED\").\n\n// ACHIEVEMENT: unknown > reject\n+!review_decided(Cid)\n   :  review_pending(Label, Cid) & not known_food(Label)\n   <- .send(main, tell, review_rejected(Cid, \"not in knowledge base\"));\n      +review_rejected(Cid);\n      ?review_decided(Cid);\n      .println(\"[Reviewer] '\", Label, \"' is unknown > DISAPPROVED\").\n\n// RECOVERY\n-!review_decided(Cid)\n   <- .println(\"[Reviewer] Decision FAILED for \", Cid).", "astra/acceptance-patterns/pattern-6-belief-consistency/src/main/astra/PatternRunner.astra": "// Pipeline: main > !classified > !consistent > !belief_checked\n// Pattern 6: Belief Consistency - ASTRA\n//\n// Compare the LLM candidate with existing beliefs. Confirm matches,\n// reject contradictions, and explicitly add new domain facts only when no prior belief exists.\nagent PatternRunner {\n    module gl.astra.GL gl;\n    module Console console;\n    module System S;\n\n    types governance {\n        formula binding(string);\n        formula confirmed(string);\n        formula rejected(string);\n        formula adopted_new(string);\n        formula consistent(string);\n        formula category(string, string);\n    }\n\n    initial category(\"apple\", \"fruit\"), category(\"carrot\", \"vegetable\");\n\n    inference consistent(string cid) :- confirmed(cid);\n    inference consistent(string cid) :- rejected(cid);\n    inference consistent(string cid) :- adopted_new(cid);\n\n    rule +!main(list args) {\n        !banner();\n        +binding(gl.bind(\"agent1\", \"groq\", \"openai/gpt-oss-120b\", \"\"));\n        !classified(\"house\");\n        !shutdown();\n    }\n\n    // ACHIEVEMENT: clean exit\n    rule +!shutdown() {\n        S.exit();\n    }\n\n    // ACHIEVEMENT: display banner\n    rule +!banner() {\n        console.println(\"=== Pattern 6: Belief Consistency ===\");\n        console.println(\"\");\n        console.println(\"[Layer] Available providers: \" + gl.see());\n    }\n\n    // DECOMPOSITION: classify = call + deliberate\n    rule +!classified(string item) : binding(string bid) {\n        !consistent(gl.call(bid, \"classify\", \"llm.answer\", \"ANSWER\",\n            \"Classify: \" + item + \". Return only a label field.\", \"label\", \"\"), item);\n    }\n\n    // SERENDIPITY: already checked\n    rule +!consistent(string rid, string item) : consistent(gl.candidate(rid)) {\n        console.println(\"[AGENT] Already checked: \" + rid);\n    }\n\n    // DECOMPOSITION: admissible > check belief consistency\n    rule +!consistent(string rid, string item) : gl.decide(gl.candidate(rid)) == \"ADMISSIBLE\" {\n        !belief_checked(rid, gl.candidate(rid), item, gl.get(gl.candidate(rid), \"label\"));\n    }\n\n    // DECOMPOSITION: not admissible > reject\n    rule +!consistent(string rid, string item) {\n        !rejected_candidate(gl.candidate(rid), rid);\n    }\n\n    // ACHIEVEMENT: match belief > confirm\n    rule +!belief_checked(string rid, string cid, string item, string label) : category(item, label) {\n        gl.accept(cid, \"matches existing belief\");\n        +confirmed(cid);\n        console.println(\"Matches belief - CONFIRMED\");\n        console.println(\"  Accepted candidate: \" + cid);\n        console.println(\"  LLM label: \" + label);\n        console.println(\"  Reason: matches existing belief\");\n        !print_trace(rid);\n        console.println(\"=== Demo Complete ===\");\n    }\n\n    // ACHIEVEMENT: contradicts belief > reject\n    rule +!belief_checked(string rid, string cid, string item, string label) : category(item, string existing) & ~category(item, label) {\n        gl.reject(cid, \"contradicts belief: \" + existing);\n        +rejected(cid);\n        console.println(\"Contradicts belief - REJECTED\");\n        console.println(\"  Rejected candidate: \" + cid);\n        console.println(\"  LLM label: \" + label);\n        console.println(\"  Existing belief: \" + existing);\n        console.println(\"  Reason: contradicts existing belief\");\n        !print_trace(rid);\n        console.println(\"=== Demo Complete ===\");\n    }\n\n    // ACHIEVEMENT: no prior belief, but label is a known valid category -> explicitly add new domain fact\n    rule +!belief_checked(string rid, string cid, string item, string label) : ~category(item, string any) & category(string _, label) {\n        gl.accept(cid, \"no prior belief: \" + label);\n        +category(item, label);\n        +adopted_new(cid);\n        console.println(\"No prior belief, valid category - NEW DOMAIN BELIEF ADDED\");\n        console.println(\"  Accepted candidate: \" + cid);\n        console.println(\"  LLM label: \" + label);\n        console.println(\"  Reason: no prior belief existed, category is known\");\n        !print_trace(rid);\n        console.println(\"=== Demo Complete ===\");\n    }\n\n    // ACHIEVEMENT: no prior belief, and label is NOT a known valid category -> reject\n    rule +!belief_checked(string rid, string cid, string item, string label) : ~category(item, string any) {\n        gl.reject(cid, \"invalid category: \" + label);\n        +rejected(cid);\n        console.println(\"Invalid category label - REJECTED\");\n        console.println(\"  Rejected candidate: \" + cid);\n        console.println(\"  LLM label: \" + label);\n        console.println(\"  Reason: category is not one of the allowed classes\");\n        !print_trace(rid);\n        console.println(\"=== Demo Complete ===\");\n    }\n\n    // ACHIEVEMENT: reject (actions only)\n    rule +!rejected_candidate(string cid, string rid) {\n        gl.reject(cid, \"failed validation\");\n        +rejected(cid);\n        console.println(\"Invalid output - REJECTED\");\n        console.println(\"  Rejected candidate: \" + cid);\n        console.println(\"  Reason: failed schema validation\");\n        !print_trace(rid);\n    }\n\n    // ACHIEVEMENT: print trace\n    rule +!print_trace(string rid) {\n        console.println(\"\");\n        console.println(\"[TRACE] \" + gl.explain(rid));\n    }\n\n    // RECOVERY\n    rule -!consistent(string rid, string item) : ~confirmed(string _) & ~rejected(string _) & ~adopted_new(string _) {\n        console.println(\"Consistency check FAILED for \" + rid);\n    }\n}", "jason/acceptance-patterns/pattern-6-belief-consistency/src/main/asl/main.asl": "// Pipeline: start > !banner > !classified > !consistent > !belief_checked | !rejected_candidate\n/**\n * Pattern 6: Belief Consistency - Jason\n *\n * Compare the LLM candidate with existing beliefs. Confirm matches,\n * reject contradictions, and explicitly add new domain facts only when no prior belief exists.\n */\n\n// Requires: GL ontology beliefs (gl_status, gl_candidate_type, gl_verdict_type, ...)\n//   See: https://github.com/generativelayers/examples/tree/main/jason/shared\n\ncategory(\"apple\", \"fruit\"). category(\"carrot\", \"vegetable\").\n\n// DOMAIN MODEL\nconsistent(Cid) :- confirmed(Cid).\nconsistent(Cid) :- rejected(Cid).\nconsistent(Cid) :- adopted_new(Cid).\nhas_candidate(Cid) :- Cid \\== \"\".\nno_candidate(Cid)  :- Cid == \"\".\n\n!start.\n\n// DECOMPOSITION: start only adopts subgoals\n+!start\n   <- !banner;\n      gl.bind(\"agent1\", \"groq\", \"openai/gpt-oss-120b\", \"\", Bid);\n      +binding(Bid);\n      !classified(\"house\");\n      !shutdown.\n\n// ACHIEVEMENT: clean exit\n+!shutdown\n   <- .stopMAS.\n\n// ACHIEVEMENT: display banner\n+!banner\n   :  gl.see(Providers)\n   <- .println(\"=== Pattern 6: Belief Consistency ===\");\n      .println(\"\");\n      .println(\"[Layer] Available providers: \", Providers).\n\n// DECOMPOSITION: classify = call + deliberate\n+!classified(Item)\n   :  binding(Bid)\n   <- .concat(\"Classify: \", Item, \". Return only a label field.\", Prompt);\n      gl.call(Bid, \"classify\", \"llm.answer\", \"ANSWER\", Prompt, \"label\", \"\", Rid);\n      !consistent(Rid, Item).\n\n// SERENDIPITY: already checked\n+!consistent(Rid, Item)\n   :  gl.candidate(Rid, Cid) & consistent(Cid)\n   <- .println(\"[AGENT] Already checked: \", Rid).\n\n// DECOMPOSITION: admissible > check belief consistency\n+!consistent(Rid, Item)\n   :  gl.candidate(Rid, Cid) & gl.decide(Cid, \"ADMISSIBLE\") & gl.get(Cid, \"label\", Label)\n   <- !belief_checked(Rid, Cid, Item, Label).\n\n// DECOMPOSITION: not admissible > reject\n+!consistent(Rid, Item)\n   :  gl.candidate(Rid, Cid)\n   <- !rejected_candidate(Cid, Rid).\n\n// ACHIEVEMENT: match belief > confirm\n+!belief_checked(Rid, Cid, Item, Label)\n   :  category(Item, Label)\n   <- gl.accept(Cid, \"matches existing belief\", _);\n      +confirmed(Cid);\n      .println(\"Matches belief - CONFIRMED\");\n      .println(\"  Accepted candidate: \", Cid);\n      .println(\"  LLM label: \", Label);\n      .println(\"  Reason: matches existing belief\");\n      !print_trace(Rid);\n      .println(\"=== Demo Complete ===\").\n\n// ACHIEVEMENT: contradicts belief > reject\n+!belief_checked(Rid, Cid, Item, Label)\n   :  category(Item, Existing) & Existing \\== Label\n   <- .concat(\"contradicts belief: \", Existing, Reason);\n      gl.reject(Cid, Reason, _);\n      +rejected(Cid);\n      .println(\"Contradicts belief - REJECTED\");\n      .println(\"  Rejected candidate: \", Cid);\n      .println(\"  LLM label: \", Label);\n      .println(\"  Existing belief: \", Existing);\n      .println(\"  Reason: contradicts existing belief\");\n      !print_trace(Rid);\n      .println(\"=== Demo Complete ===\").\n\n// ACHIEVEMENT: no prior belief, but label is a known valid category -> explicitly add new domain fact\n+!belief_checked(Rid, Cid, Item, Label)\n   :  not category(Item, _) & category(_, Label)\n   <- .concat(\"no prior belief, valid category: \", Label, Reason);\n      gl.accept(Cid, Reason, _);\n      +category(Item, Label);\n      +adopted_new(Cid);\n      .println(\"No prior belief, valid category - NEW DOMAIN BELIEF ADDED\");\n      .println(\"  Accepted candidate: \", Cid);\n      .println(\"  LLM label: \", Label);\n      .println(\"  Reason: no prior belief existed, category is known\");\n      !print_trace(Rid);\n      .println(\"=== Demo Complete ===\").\n\n// ACHIEVEMENT: no prior belief, and label is NOT a known valid category -> reject\n+!belief_checked(Rid, Cid, Item, Label)\n   :  not category(Item, _)\n   <- .concat(\"invalid category label: \", Label, Reason);\n      gl.reject(Cid, Reason, _);\n      +rejected(Cid);\n      .println(\"Invalid category label - REJECTED\");\n      .println(\"  Rejected candidate: \", Cid);\n      .println(\"  LLM label: \", Label);\n      .println(\"  Reason: category is not one of the allowed classes\");\n      !print_trace(Rid);\n      .println(\"=== Demo Complete ===\").\n\n// ACHIEVEMENT: reject (actions only) - candidate exists\n+!rejected_candidate(Cid, Rid)\n   :  has_candidate(Cid)\n   <- gl.reject(Cid, \"failed validation\", _);\n      +rejected(Cid);\n      .println(\"Invalid output - REJECTED\");\n      .println(\"  Rejected candidate: \", Cid);\n      .println(\"  Reason: failed schema validation\");\n      !print_trace(Rid).\n\n// ACHIEVEMENT: reject (actions only) - no candidate\n+!rejected_candidate(Cid, Rid)\n   :  no_candidate(Cid) & gl.result(Rid, Outcome)\n   <- +rejected(\"\");\n      .println(\"Invocation failed - REJECTED (outcome = \", Outcome, \")\");\n      !print_trace(Rid).\n\n// ACHIEVEMENT: print trace\n+!print_trace(Rid)\n   :  gl.explain(Rid, Trace)\n   <- .println(\"\");\n      .println(\"[TRACE] \", Trace).\n\n// RECOVERY\n-!consistent(Rid, Item)\n   :  not confirmed(_) & not rejected(_) & not adopted_new(_)\n   <- .println(\"Consistency check FAILED for \", Rid).", "jacamo/acceptance-patterns/pattern-6-belief-consistency/src/agt/main.asl": "// Pipeline: start > !banner > !classified > !consistent > !belief_checked | !rejected_candidate\n/**\n * Pattern 6: Belief Consistency - JaCaMo\n *\n * Compare the LLM candidate with existing beliefs. Confirm matches,\n * reject contradictions, and explicitly add new domain facts only when no prior belief exists.\n */\n\ncategory(\"apple\", \"fruit\"). category(\"carrot\", \"vegetable\").\n\n// DOMAIN MODEL\nconsistent(Cid) :- confirmed(Cid).\nconsistent(Cid) :- rejected(Cid).\nconsistent(Cid) :- adopted_new(Cid).\nhas_candidate(Cid) :- Cid \\== \"\".\nno_candidate(Cid)  :- Cid == \"\".\n\n!start.\n\n// DECOMPOSITION: start only adopts subgoals\n+!start\n   <- !artifact_ready;\n      !banner;\n      bind(\"agent1\", \"groq\", \"openai/gpt-oss-120b\", \"\", Bid);\n      +binding(Bid);\n      !classified(\"house\");\n      !shutdown.\n\n// ACHIEVEMENT: create and focus the GL artifact\n+!artifact_ready\n   <- makeArtifact(\"gl\", \"gl.jacamo.GL\", [], GlId);\n      focus(GlId).\n\n// ACHIEVEMENT: clean exit\n+!shutdown\n   <- .stopMAS.\n\n// ACHIEVEMENT: display banner\n+!banner\n   <- see(Providers);\n      .println(\"=== Pattern 6: Belief Consistency ===\");\n      .println(\"\");\n      .println(\"[Layer] Available providers: \", Providers).\n\n// DECOMPOSITION: classify = call + deliberate\n+!classified(Item)\n   :  binding(Bid)\n   <- .concat(\"Classify: \", Item, \". Return only a label field.\", Prompt);\n      call(Bid, \"classify\", \"llm.answer\", \"ANSWER\", Prompt, \"label\", \"\", Rid);\n      !consistent(Rid, Item).\n\n// SERENDIPITY: already checked\n+!consistent(Rid, Item)\n   :  consistent(Cid) & candidate(Rid, Cid)\n   <- .println(\"[AGENT] Already checked: \", Rid).\n\n// DECOMPOSITION: handle deliberation\n+!consistent(Rid, Item)\n   <- candidate(Rid, Cid);\n      !consistent_candidate(Rid, Item, Cid).\n\n+!consistent_candidate(Rid, Item, Cid)\n   :  has_candidate(Cid)\n   <- decide(Cid, Admissibility);\n      !consistent_decision(Rid, Item, Cid, Admissibility).\n\n+!consistent_candidate(Rid, Item, Cid)\n   :  no_candidate(Cid)\n   <- result(Rid, Outcome);\n      !consistent_decision(Rid, Item, Cid, Outcome).\n\n// DECOMPOSITION: route decision\n+!consistent_decision(Rid, Item, Cid, \"ADMISSIBLE\")\n   <- get(Cid, \"label\", Label);\n      !belief_checked(Rid, Cid, Item, Label).\n\n+!consistent_decision(Rid, Item, Cid, Outcome)\n   <- !rejected_candidate(Cid, Rid, Outcome).\n\n// ACHIEVEMENT: match belief > confirm\n+!belief_checked(Rid, Cid, Item, Label)\n   :  category(Item, Label)\n   <- accept(Cid, \"matches existing belief\", _);\n      +confirmed(Cid);\n      .println(\"Matches belief - CONFIRMED\");\n      .println(\"  Accepted candidate: \", Cid);\n      .println(\"  LLM label: \", Label);\n      .println(\"  Reason: matches existing belief\");\n      !print_trace(Rid);\n      .println(\"=== Demo Complete ===\").\n\n// ACHIEVEMENT: contradicts belief > reject\n+!belief_checked(Rid, Cid, Item, Label)\n   :  category(Item, Existing) & Existing \\== Label\n   <- .concat(\"contradicts belief: \", Existing, Reason);\n      reject(Cid, Reason, _);\n      +rejected(Cid);\n      .println(\"Contradicts belief - REJECTED\");\n      .println(\"  Rejected candidate: \", Cid);\n      .println(\"  LLM label: \", Label);\n      .println(\"  Existing belief: \", Existing);\n      .println(\"  Reason: contradicts existing belief\");\n      !print_trace(Rid);\n      .println(\"=== Demo Complete ===\").\n\n// ACHIEVEMENT: no prior belief, but label is a known valid category -> explicitly add new domain fact\n+!belief_checked(Rid, Cid, Item, Label)\n   :  not category(Item, _) & category(_, Label)\n   <- .concat(\"no prior belief, valid category: \", Label, Reason);\n      accept(Cid, Reason, _);\n      +category(Item, Label);\n      +adopted_new(Cid);\n      .println(\"No prior belief, valid category - NEW DOMAIN BELIEF ADDED\");\n      .println(\"  Accepted candidate: \", Cid);\n      .println(\"  LLM label: \", Label);\n      .println(\"  Reason: no prior belief existed, category is known\");\n      !print_trace(Rid);\n      .println(\"=== Demo Complete ===\").\n\n// ACHIEVEMENT: no prior belief, and label is NOT a known valid category -> reject\n+!belief_checked(Rid, Cid, Item, Label)\n   :  not category(Item, _)\n   <- .concat(\"invalid category label: \", Label, Reason);\n      reject(Cid, Reason, _);\n      +rejected(Cid);\n      .println(\"Invalid category label - REJECTED\");\n      .println(\"  Rejected candidate: \", Cid);\n      .println(\"  LLM label: \", Label);\n      .println(\"  Reason: category is not one of the allowed classes\");\n      !print_trace(Rid);\n      .println(\"=== Demo Complete ===\").\n\n// ACHIEVEMENT: reject (actions only) - candidate exists\n+!rejected_candidate(Cid, Rid, Outcome)\n   :  has_candidate(Cid)\n   <- reject(Cid, \"failed validation\", _);\n      +rejected(Cid);\n      .println(\"Invalid output - REJECTED\");\n      .println(\"  Rejected candidate: \", Cid);\n      .println(\"  Reason: failed schema validation\");\n      !print_trace(Rid).\n\n// ACHIEVEMENT: reject (actions only) - no candidate\n+!rejected_candidate(Cid, Rid, Outcome)\n   :  no_candidate(Cid)\n   <- +rejected(\"\");\n      .println(\"Invocation failed - REJECTED (outcome = \", Outcome, \")\");\n      !print_trace(Rid).\n\n// ACHIEVEMENT: print trace\n+!print_trace(Rid)\n   <- explain(Rid, Trace);\n      .println(\"\");\n      .println(\"[TRACE] \", Trace).\n\n// RECOVERY\n-!consistent(Rid, Item)\n   :  not confirmed(_) & not rejected(_) & not adopted_new(_)\n   <- .println(\"Consistency check FAILED for \", Rid).", "astra/acceptance-patterns/pattern-7-majority-voting/src/main/astra/PatternRunner.astra": "// Pipeline: main > !vote_cast(1..3) > !vote_recorded > !consensus_reached\n// Pattern 7: Majority Voting - ASTRA\n//\n// Collect multiple candidate votes and record acceptance for the concrete\n// candidates that form a majority.\nagent PatternRunner {\n    module gl.astra.GL gl;\n    module Console console;\n    module System S;\n\n    types governance {\n        formula binding(int, string);\n        formula vote(int, string, string, string);\n        formula consensus_label(string);\n        formula consensus_reached(boolean);\n        formula no_consensus(boolean);\n    }\n\n    // DOMAIN MODEL\n    inference consensus_reached(true) :- consensus_label(string _);\n    inference consensus_reached(true) :- no_consensus(true);\n\n    rule +!main(list args) {\n        !banner();\n        +binding(1, gl.bind(\"agent1\", \"groq\", \"openai/gpt-oss-120b\", \"\"));\n        +binding(2, gl.bind(\"agent2\", \"cerebras\", \"gpt-oss-120b\", \"\"));\n        +binding(3, gl.bind(\"agent3\", \"groq\", \"openai/gpt-oss-120b\", \"\"));\n        !classified(\"tomato\");\n        !shutdown();\n    }\n\n    // ACHIEVEMENT: clean exit\n    rule +!shutdown() {\n        S.exit();\n    }\n\n    // ACHIEVEMENT: display banner\n    rule +!banner() {\n        console.println(\"=== Pattern 7: Majority Voting ===\");\n        console.println(\"\");\n        console.println(\"[Layer] Available providers: \" + gl.see());\n    }\n\n    // DECOMPOSITION: classify = cast 3 votes + check consensus\n    rule +!classified(string item) : binding(1, string bid1) & binding(2, string bid2) & binding(3, string bid3) {\n        !vote_cast(1, bid1, item);\n        !vote_cast(2, bid2, item);\n        !vote_cast(3, bid3, item);\n        !consensus_reached(true);\n    }\n\n    // DECOMPOSITION: cast vote\n    rule +!vote_cast(int id, string bid, string item) {\n        !vote_recorded(id, gl.call(bid, \"classify\", \"llm.answer\", \"ANSWER\",\n            \"Classify: \" + item + \". Return only a label field.\", \"label\", \"\"));\n    }\n\n    // DECOMPOSITION: vote valid > record\n    rule +!vote_recorded(int id, string rid) : gl.decide(gl.candidate(rid)) == \"ADMISSIBLE\" {\n        +vote(id, rid, gl.candidate(rid), gl.get(gl.candidate(rid), \"label\"));\n        console.println(\"[Vote \" + id + \"] label = \" + gl.get(gl.candidate(rid), \"label\"));\n    }\n\n    // DECOMPOSITION: vote invalid > record failure\n    rule +!vote_recorded(int id, string rid) {\n        +vote(id, rid, gl.candidate(rid), \"INVALID\");\n        console.println(\"[Vote \" + id + \"] output invalid\");\n    }\n\n    // SERENDIPITY: consensus already reached\n    rule +!consensus_reached(boolean x) : consensus_reached(true) & consensus_label(string winner) {\n        console.println(\"Already have consensus: \" + winner);\n    }\n\n    // ACHIEVEMENT: tally votes 1 & 2 match\n    rule +!consensus_reached(boolean x) :\n            vote(1, string r1, string c1, string l1) &\n            vote(2, string r2, string c2, string l2) &\n            vote(3, string r3, string c3, string l3) &\n            l1 == l2 & l1 ~= \"INVALID\" {\n        gl.accept(c1, \"majority vote\");\n        gl.accept(c2, \"majority vote\");\n        +consensus_label(l1);\n        console.println(\"Majority (votes 1 & 2): '\" + l1 + \"' - ACCEPTANCE RECORDED\");\n        !print_trace(r1);\n        !print_trace(r2);\n        !print_trace(r3);\n        console.println(\"=== Demo Complete ===\");\n    }\n\n    // ACHIEVEMENT: tally votes 1 & 3 match\n    rule +!consensus_reached(boolean x) :\n            vote(1, string r1, string c1, string l1) &\n            vote(2, string r2, string c2, string l2) &\n            vote(3, string r3, string c3, string l3) &\n            l1 == l3 & l1 ~= \"INVALID\" {\n        gl.accept(c1, \"majority vote\");\n        gl.accept(c3, \"majority vote\");\n        +consensus_label(l1);\n        console.println(\"Majority (votes 1 & 3): '\" + l1 + \"' - ACCEPTANCE RECORDED\");\n        !print_trace(r1);\n        !print_trace(r2);\n        !print_trace(r3);\n        console.println(\"=== Demo Complete ===\");\n    }\n\n    // ACHIEVEMENT: tally votes 2 & 3 match\n    rule +!consensus_reached(boolean x) :\n            vote(1, string r1, string c1, string l1) &\n            vote(2, string r2, string c2, string l2) &\n            vote(3, string r3, string c3, string l3) &\n            l2 == l3 & l2 ~= \"INVALID\" {\n        gl.accept(c2, \"majority vote\");\n        gl.accept(c3, \"majority vote\");\n        +consensus_label(l2);\n        console.println(\"Majority (votes 2 & 3): '\" + l2 + \"' - ACCEPTANCE RECORDED\");\n        !print_trace(r1);\n        !print_trace(r2);\n        !print_trace(r3);\n        console.println(\"=== Demo Complete ===\");\n    }\n\n    // ACHIEVEMENT: no majority consensus\n    rule +!consensus_reached(boolean x) :\n            vote(1, string r1, string c1, string l1) &\n            vote(2, string r2, string c2, string l2) &\n            vote(3, string r3, string c3, string l3) {\n        gl.reject(c1, \"no majority consensus\");\n        gl.reject(c2, \"no majority consensus\");\n        gl.reject(c3, \"no majority consensus\");\n        +no_consensus(true);\n        console.println(\"No majority - NO CONSENSUS\");\n        !print_trace(r1);\n        !print_trace(r2);\n        !print_trace(r3);\n        console.println(\"=== Demo Complete ===\");\n    }\n\n    // ACHIEVEMENT: print trace\n    rule +!print_trace(string rid) {\n        console.println(\"\");\n        console.println(\"[TRACE] \" + gl.explain(rid));\n    }\n\n    // RECOVERY\n    rule -!consensus_reached(boolean x) : ~consensus_label(string _) & ~no_consensus(true) {\n        console.println(\"Consensus FAILED\");\n    }\n\n    rule -!vote_recorded(int id, string rid) : ~vote(id, string _, string _, string _) {\n        console.println(\"Vote \" + id + \" FAILED\");\n    }\n}", "jason/acceptance-patterns/pattern-7-majority-voting/src/main/asl/main.asl": "// Pipeline: start > !banner > !classified > !vote_cast(1..3) > !vote_recorded > !consensus_reached\n/**\n * Pattern 7: Majority Voting - Jason\n *\n * Collect multiple candidate votes and record acceptance for the concrete\n * candidates that form a majority.\n */\n\n// Requires: GL ontology beliefs (gl_status, gl_candidate_type, gl_verdict_type, ...)\n//   See: https://github.com/generativelayers/examples/tree/main/jason/shared\n\n// DOMAIN MODEL\nconsensus_reached(true) :- consensus_label(_).\nconsensus_reached(true) :- no_consensus(true).\n\n!start.\n\n// DECOMPOSITION: start only adopts subgoals\n+!start\n   <- !banner;\n      gl.bind(\"agent1\", \"groq\", \"openai/gpt-oss-120b\", \"\", Bid1);\n      +binding(1, Bid1);\n      gl.bind(\"agent2\", \"cerebras\", \"gpt-oss-120b\", \"\", Bid2);\n      +binding(2, Bid2);\n      gl.bind(\"agent3\", \"groq\", \"openai/gpt-oss-120b\", \"\", Bid3);\n      +binding(3, Bid3);\n      !classified(\"tomato\");\n      !shutdown.\n\n// ACHIEVEMENT: clean exit\n+!shutdown\n   <- .stopMAS.\n\n// ACHIEVEMENT: display banner\n+!banner\n   :  gl.see(Providers)\n   <- .println(\"=== Pattern 7: Majority Voting ===\");\n      .println(\"\");\n      .println(\"[Layer] Available providers: \", Providers).\n\n// DECOMPOSITION: classify = cast 3 votes + check consensus\n+!classified(Item)\n   :  binding(1, Bid1) & binding(2, Bid2) & binding(3, Bid3)\n   <- !vote_cast(1, Bid1, Item);\n      !vote_cast(2, Bid2, Item);\n      !vote_cast(3, Bid3, Item);\n      !consensus_reached(true).\n\n// DECOMPOSITION: cast vote\n+!vote_cast(Id, Bid, Item)\n   <- .concat(\"Classify: \", Item, \". Return only a label field.\", Prompt);\n      gl.call(Bid, \"classify\", \"llm.answer\", \"ANSWER\", Prompt, \"label\", \"\", Rid);\n      !vote_recorded(Id, Rid).\n\n// DECOMPOSITION: vote valid > record\n+!vote_recorded(Id, Rid)\n   :  gl.candidate(Rid, Cid) & gl.decide(Cid, \"ADMISSIBLE\") & gl.get(Cid, \"label\", Label)\n   <- +vote(Id, Rid, Cid, Label);\n      .println(\"[Vote \", Id, \"] label = \", Label).\n\n// DECOMPOSITION: vote invalid > record failure\n+!vote_recorded(Id, Rid)\n   :  gl.candidate(Rid, Cid)\n   <- +vote(Id, Rid, Cid, \"INVALID\");\n      .println(\"[Vote \", Id, \"] output invalid\").\n\n// SERENDIPITY: consensus already reached\n+!consensus_reached(X)\n   :  consensus_reached(true) & consensus_label(Winner)\n   <- .println(\"Already have consensus: \", Winner).\n\n// ACHIEVEMENT: tally votes 1 & 2 match\n+!consensus_reached(X)\n   :  vote(1, R1, C1, L1) &\n      vote(2, R2, C2, L2) &\n      vote(3, R3, C3, L3) &\n      L1 == L2 & L1 \\== \"INVALID\"\n   <- gl.accept(C1, \"majority vote\", _);\n      gl.accept(C2, \"majority vote\", _);\n      +consensus_label(L1);\n      .println(\"Majority (votes 1 & 2): '\", L1, \"' - ACCEPTANCE RECORDED\");\n      !print_trace(R1);\n      !print_trace(R2);\n      !print_trace(R3);\n      .println(\"=== Demo Complete ===\").\n\n// ACHIEVEMENT: tally votes 1 & 3 match\n+!consensus_reached(X)\n   :  vote(1, R1, C1, L1) &\n      vote(2, R2, C2, L2) &\n      vote(3, R3, C3, L3) &\n      L1 == L3 & L1 \\== \"INVALID\"\n   <- gl.accept(C1, \"majority vote\", _);\n      gl.accept(C3, \"majority vote\", _);\n      +consensus_label(L1);\n      .println(\"Majority (votes 1 & 3): '\", L1, \"' - ACCEPTANCE RECORDED\");\n      !print_trace(R1);\n      !print_trace(R2);\n      !print_trace(R3);\n      .println(\"=== Demo Complete ===\").\n\n// ACHIEVEMENT: tally votes 2 & 3 match\n+!consensus_reached(X)\n   :  vote(1, R1, C1, L1) &\n      vote(2, R2, C2, L2) &\n      vote(3, R3, C3, L3) &\n      L2 == L3 & L2 \\== \"INVALID\"\n   <- gl.accept(C2, \"majority vote\", _);\n      gl.accept(C3, \"majority vote\", _);\n      +consensus_label(L2);\n      .println(\"Majority (votes 2 & 3): '\", L2, \"' - ACCEPTANCE RECORDED\");\n      !print_trace(R1);\n      !print_trace(R2);\n      !print_trace(R3);\n      .println(\"=== Demo Complete ===\").\n\n// ACHIEVEMENT: no majority consensus\n+!consensus_reached(X)\n   :  vote(1, R1, C1, L1) &\n      vote(2, R2, C2, L2) &\n      vote(3, R3, C3, L3)\n   <- gl.reject(C1, \"no majority consensus\", _);\n      gl.reject(C2, \"no majority consensus\", _);\n      gl.reject(C3, \"no majority consensus\", _);\n      +no_consensus(true);\n      .println(\"No majority - NO CONSENSUS\");\n      !print_trace(R1);\n      !print_trace(R2);\n      !print_trace(R3);\n      .println(\"=== Demo Complete ===\").\n\n// ACHIEVEMENT: print trace\n+!print_trace(Rid)\n   :  gl.explain(Rid, Trace)\n   <- .println(\"\");\n      .println(\"[TRACE] \", Trace).\n\n// RECOVERY\n-!consensus_reached(X)\n   :  not consensus_label(_) & not no_consensus(true)\n   <- .println(\"Consensus FAILED\").\n\n-!vote_recorded(Id, Rid)\n   :  not vote(Id, _, _, _)\n   <- .println(\"Vote \", Id, \" FAILED\").", "jacamo/acceptance-patterns/pattern-7-majority-voting/src/agt/main.asl": "// Pipeline: start > !banner > !classified > !vote_cast(1..3) > !vote_recorded > !consensus_reached\n/**\n * Pattern 7: Majority Voting - JaCaMo\n *\n * Collect multiple candidate votes and record acceptance for the concrete\n * candidates that form a majority.\n */\n\n// DOMAIN MODEL\nconsensus_reached(true) :- consensus_label(_).\nconsensus_reached(true) :- no_consensus(true).\nhas_candidate(Cid) :- Cid \\== \"\".\nno_candidate(Cid)  :- Cid == \"\".\n\n!start.\n\n// DECOMPOSITION: start only adopts subgoals\n+!start\n   <- !artifact_ready;\n      !banner;\n      bind(\"agent1\", \"groq\", \"openai/gpt-oss-120b\", \"\", Bid1);\n      +binding(1, Bid1);\n      bind(\"agent2\", \"cerebras\", \"gpt-oss-120b\", \"\", Bid2);\n      +binding(2, Bid2);\n      bind(\"agent3\", \"groq\", \"openai/gpt-oss-120b\", \"\", Bid3);\n      +binding(3, Bid3);\n      !classified(\"tomato\");\n      !shutdown.\n\n// ACHIEVEMENT: create and focus the GL artifact\n+!artifact_ready\n   \t\t<- makeArtifact(\"gl\", \"gl.jacamo.GL\", [], GlId);\n      focus(GlId).\n\n// ACHIEVEMENT: clean exit\n+!shutdown\n   <- .stopMAS.\n\n// ACHIEVEMENT: display banner\n+!banner\n   <- see(Providers);\n      .println(\"=== Pattern 7: Majority Voting ===\");\n      .println(\"\");\n      .println(\"[Layer] Available providers: \", Providers).\n\n// DECOMPOSITION: classify = cast 3 votes + check consensus\n+!classified(Item)\n   :  binding(1, Bid1) & binding(2, Bid2) & binding(3, Bid3)\n   <- !vote_cast(1, Bid1, Item);\n      !vote_cast(2, Bid2, Item);\n      !vote_cast(3, Bid3, Item);\n      !consensus_reached(true).\n\n// DECOMPOSITION: cast vote\n+!vote_cast(Id, Bid, Item)\n   <- .concat(\"Classify: \", Item, \". Return only a label field.\", Prompt);\n      call(Bid, \"classify\", \"llm.answer\", \"ANSWER\", Prompt, \"label\", \"\", Rid);\n      !vote_recorded(Id, Rid).\n\n// DECOMPOSITION: handle deliberation for vote\n+!vote_recorded(Id, Rid)\n   <- candidate(Rid, Cid);\n      !vote_candidate(Id, Rid, Cid).\n\n+!vote_candidate(Id, Rid, Cid)\n   :  has_candidate(Cid)\n   <- decide(Cid, Admissibility);\n      !vote_decision(Id, Rid, Cid, Admissibility).\n\n+!vote_candidate(Id, Rid, Cid)\n   :  no_candidate(Cid)\n   <- result(Rid, Outcome);\n      !vote_decision(Id, Rid, Cid, Outcome).\n\n// DECOMPOSITION: route decision for vote\n+!vote_decision(Id, Rid, Cid, \"ADMISSIBLE\")\n   <- get(Cid, \"label\", Label);\n      +vote(Id, Rid, Cid, Label);\n      .println(\"[Vote \", Id, \"] label = \", Label).\n\n+!vote_decision(Id, Rid, Cid, Outcome)\n   <- +vote(Id, Rid, Cid, \"INVALID\");\n      .println(\"[Vote \", Id, \"] output invalid\").\n\n// SERENDIPITY: consensus already reached\n+!consensus_reached(X)\n   :  consensus_reached(true) & consensus_label(Winner)\n   <- .println(\"Already have consensus: \", Winner).\n\n// ACHIEVEMENT: tally votes 1 & 2 match\n+!consensus_reached(X)\n   :  vote(1, R1, C1, L1) &\n      vote(2, R2, C2, L2) &\n      vote(3, R3, C3, L3) &\n      L1 == L2 & L1 \\== \"INVALID\"\n   <- accept(C1, \"majority vote\", _);\n      accept(C2, \"majority vote\", _);\n      +consensus_label(L1);\n      .println(\"Majority (votes 1 & 2): '\", L1, \"' - ACCEPTANCE RECORDED\");\n      !print_trace(R1);\n      !print_trace(R2);\n      !print_trace(R3);\n      .println(\"=== Demo Complete ===\").\n\n// ACHIEVEMENT: tally votes 1 & 3 match\n+!consensus_reached(X)\n   :  vote(1, R1, C1, L1) &\n      vote(2, R2, C2, L2) &\n      vote(3, R3, C3, L3) &\n      L1 == L3 & L1 \\== \"INVALID\"\n   <- accept(C1, \"majority vote\", _);\n      accept(C3, \"majority vote\", _);\n      +consensus_label(L1);\n      .println(\"Majority (votes 1 & 3): '\", L1, \"' - ACCEPTANCE RECORDED\");\n      !print_trace(R1);\n      !print_trace(R2);\n      !print_trace(R3);\n      .println(\"=== Demo Complete ===\").\n\n// ACHIEVEMENT: tally votes 2 & 3 match\n+!consensus_reached(X)\n   :  vote(1, R1, C1, L1) &\n      vote(2, R2, C2, L2) &\n      vote(3, R3, C3, L3) &\n      L2 == L3 & L2 \\== \"INVALID\"\n   <- accept(C2, \"majority vote\", _);\n      accept(C3, \"majority vote\", _);\n      +consensus_label(L2);\n      .println(\"Majority (votes 2 & 3): '\", L2, \"' - ACCEPTANCE RECORDED\");\n      !print_trace(R1);\n      !print_trace(R2);\n      !print_trace(R3);\n      .println(\"=== Demo Complete ===\").\n\n// ACHIEVEMENT: no majority consensus\n+!consensus_reached(X)\n   :  vote(1, R1, C1, L1) &\n      vote(2, R2, C2, L2) &\n      vote(3, R3, C3, L3)\n   <- reject(C1, \"no majority consensus\", _);\n      reject(C2, \"no majority consensus\", _);\n      reject(C3, \"no majority consensus\", _);\n      +no_consensus(true);\n      .println(\"No majority - NO CONSENSUS\");\n      !print_trace(R1);\n      !print_trace(R2);\n      !print_trace(R3);\n      .println(\"=== Demo Complete ===\").\n\n// ACHIEVEMENT: print trace\n+!print_trace(Rid)\n   <- explain(Rid, Trace);\n      .println(\"\");\n      .println(\"[TRACE] \", Trace).\n\n// RECOVERY\n-!consensus_reached(X)\n   :  not consensus_label(_) & not no_consensus(true)\n   <- .println(\"Consensus FAILED\").\n\n-!vote_recorded(Id, Rid)\n   :  not vote(Id, _, _, _)\n   <- .println(\"Vote \", Id, \" FAILED\").", "astra/acceptance-patterns/pattern-8-iterative-refinement/src/main/astra/PatternRunner.astra": "// Pipeline: main > !drafted > !checked > !revised > !accepted_final\n/**\n * Pattern 8: Iterative Refinement - ASTRA\n *\n * Generate, check, refine, and record acceptance only for the final refined\n * candidate. Free-text outputs use the framework's text field.\n */\nagent PatternRunner {\n    module gl.astra.GL gl;\n    module Console console;\n    module System S;\n\n    types governance {\n        formula binding(string);\n        formula refined(string);\n    }\n\n    // DECOMPOSITION: main -> setup -> draft\n    rule +!main(list args) {\n        !banner();\n        +binding(gl.bind(\"agent1\", \"groq\", \"openai/gpt-oss-120b\", \"\"));\n        !drafted(\"Write a short paragraph about photosynthesis.\");\n        !shutdown();\n    }\n\n    // ACHIEVEMENT: clean exit\n    rule +!shutdown() {\n        S.exit();\n    }\n\n    // ACHIEVEMENT: display banner\n    rule +!banner() {\n        console.println(\"=== Pattern 8: Iterative Refinement ===\");\n        console.println(\"\");\n        console.println(\"[Layer] Available providers: \" + gl.see());\n    }\n\n    // DECOMPOSITION: start draft\n    rule +!drafted(string prompt) : binding(string bid) {\n        !checked(gl.call(bid, \"draft\", \"llm.answer\", \"ANSWER\", prompt, \"answer\", \"\"));\n    }\n\n    // DECOMPOSITION: check draft\n    rule +!checked(string draftRid) : binding(string bid) {\n        !print_draft(draftRid);\n        !revised(draftRid, gl.call(bid, \"check\", \"llm.answer\", \"ANSWER\",\n            \"Review this text and suggest improvements: \" + gl.get(gl.candidate(draftRid), \"answer\"), \"answer\", \"\"));\n    }\n\n    // ACHIEVEMENT: print draft\n    rule +!print_draft(string draftRid) {\n        console.println(\"[Draft] \" + gl.get(gl.candidate(draftRid), \"answer\"));\n    }\n\n    // DECOMPOSITION: revise draft\n    rule +!revised(string draftRid, string checkRid) : binding(string bid) {\n        !print_check(checkRid);\n        !accepted_final(gl.call(bid, \"revise\", \"llm.answer\", \"ANSWER\",\n            \"Revise this text: \" + gl.get(gl.candidate(draftRid), \"answer\") + \" Based on: \" + gl.get(gl.candidate(checkRid), \"answer\"), \"answer\", \"\"));\n    }\n\n    // ACHIEVEMENT: print check\n    rule +!print_check(string checkRid) {\n        console.println(\"[Check] \" + gl.get(gl.candidate(checkRid), \"answer\"));\n    }\n\n    // DECOMPOSITION: accept final and print trace\n    rule +!accepted_final(string finalRid) {\n        !print_revised(finalRid);\n        !accept_candidate(gl.candidate(finalRid), finalRid);\n        !print_trace(finalRid);\n        !print_complete();\n    }\n\n    // ACHIEVEMENT: print revised\n    rule +!print_revised(string finalRid) {\n        console.println(\"[Revised] \" + gl.get(gl.candidate(finalRid), \"answer\"));\n    }\n\n    // ACHIEVEMENT: record final acceptance\n    rule +!accept_candidate(string cid, string finalRid) {\n        gl.accept(cid, \"final refined text\");\n        +refined(finalRid);\n        console.println(\"Final candidate - ACCEPTANCE RECORDED\");\n    }\n\n    // ACHIEVEMENT: print trace\n    rule +!print_trace(string rid) {\n        console.println(\"\");\n        console.println(\"[TRACE] \" + gl.explain(rid));\n    }\n\n    // ACHIEVEMENT: print complete\n    rule +!print_complete() {\n        console.println(\"=== Demo Complete ===\");\n    }\n\n    // RECOVERY\n    rule -!drafted(string prompt) : ~refined(string _) {\n        console.println(\"Pipeline FAILED\");\n    }\n}", "jason/acceptance-patterns/pattern-8-iterative-refinement/src/main/asl/main.asl": "// Pipeline: start > !banner > !drafted > !checked > !revised > !accepted_final\n/**\n * Pattern 8: Iterative Refinement - Jason\n *\n * Generate, check, refine, and record acceptance only for the final refined\n * candidate. Free-text outputs use the framework's text field.\n */\n\n// Requires: GL ontology beliefs (gl_status, gl_candidate_type, gl_verdict_type, ...)\n//   See: https://github.com/generativelayers/examples/tree/main/jason/shared\n\nrefined(FinalRid) :- accepted_final(FinalRid).\n\n!start.\n\n// DECOMPOSITION: start only adopts subgoals\n+!start\n   <- !banner;\n      gl.bind(\"agent1\", \"groq\", \"openai/gpt-oss-120b\", \"\", Bid);\n      +binding(Bid);\n      !drafted(\"Write a short paragraph about photosynthesis.\");\n      !shutdown.\n\n// ACHIEVEMENT: clean exit\n+!shutdown\n   <- .stopMAS.\n\n// ACHIEVEMENT: display banner\n+!banner\n   :  gl.see(Providers)\n   <- .println(\"=== Pattern 8: Iterative Refinement ===\");\n      .println(\"\");\n      .println(\"[Layer] Available providers: \", Providers).\n\n// DECOMPOSITION: draft\n+!drafted(Prompt)\n   :  binding(Bid)\n   <- gl.call(Bid, \"draft\", \"llm.answer\", \"ANSWER\", Prompt, \"answer\", \"\", DraftRid);\n      !checked(DraftRid).\n\n// DECOMPOSITION: check\n+!checked(DraftRid)\n   :  binding(Bid)\n   <- !print_draft(DraftRid);\n      gl.candidate(DraftRid, DraftCid);\n      gl.get(DraftCid, \"answer\", DraftText);\n      .concat(\"Review this text and suggest improvements: \", DraftText, Prompt);\n      gl.call(Bid, \"check\", \"llm.answer\", \"ANSWER\", Prompt, \"answer\", \"\", CheckRid);\n      !revised(DraftRid, CheckRid).\n\n// ACHIEVEMENT: print draft\n+!print_draft(DraftRid)\n   :  gl.candidate(DraftRid, DraftCid) & gl.get(DraftCid, \"answer\", DraftText)\n   <- .println(\"[Draft] \", DraftText).\n\n// DECOMPOSITION: revise\n+!revised(DraftRid, CheckRid)\n   :  binding(Bid)\n   <- !print_check(CheckRid);\n      gl.candidate(DraftRid, DraftCid);\n      gl.get(DraftCid, \"answer\", DraftText);\n      gl.candidate(CheckRid, CheckCid);\n      gl.get(CheckCid, \"answer\", CheckText);\n      .concat(\"Revise this text: \", DraftText, \" Based on: \", CheckText, Prompt);\n      gl.call(Bid, \"revise\", \"llm.answer\", \"ANSWER\", Prompt, \"answer\", \"\", FinalRid);\n      !accepted_final(FinalRid).\n\n// ACHIEVEMENT: print check\n+!print_check(CheckRid)\n   :  gl.candidate(CheckRid, CheckCid) & gl.get(CheckCid, \"answer\", CheckText)\n   <- .println(\"[Check] \", CheckText).\n\n// DECOMPOSITION: accept final and print trace\n+!accepted_final(FinalRid)\n   <- !print_revised(FinalRid);\n      gl.candidate(FinalRid, FinalCid);\n      !accept_candidate(FinalCid, FinalRid);\n      !print_trace(FinalRid);\n      !print_complete.\n\n// ACHIEVEMENT: print revised\n+!print_revised(FinalRid)\n   :  gl.candidate(FinalRid, FinalCid) & gl.get(FinalCid, \"answer\", FinalText)\n   <- .println(\"[Revised] \", FinalText).\n\n// ACHIEVEMENT: record final acceptance\n+!accept_candidate(FinalCid, FinalRid)\n   <- gl.accept(FinalCid, \"final refined text\", _);\n      +accepted_final(FinalRid);\n      .println(\"Final candidate - ACCEPTANCE RECORDED\").\n\n// ACHIEVEMENT: print trace\n+!print_trace(Rid)\n   :  gl.explain(Rid, Trace)\n   <- .println(\"\");\n      .println(\"[TRACE] \", Trace).\n\n// ACHIEVEMENT: print complete\n+!print_complete\n   <- .println(\"=== Demo Complete ===\").\n\n// RECOVERY\n-!drafted(Prompt)\n   :  not accepted_final(_)\n   <- .println(\"Pipeline FAILED\").", "jacamo/acceptance-patterns/pattern-8-iterative-refinement/src/agt/main.asl": "// Pipeline: start > !banner > !drafted > !checked > !revised > !accepted_final\n/**\n * Pattern 8: Iterative Refinement - JaCaMo\n *\n * Generate, check, refine, and record acceptance only for the final refined\n * candidate. Free-text outputs use the framework's text field.\n */\n\n// DOMAIN MODEL\nrefined(FinalRid) :- accepted_final(FinalRid).\nhas_candidate(Cid) :- Cid \\== \"\".\nno_candidate(Cid)  :- Cid == \"\".\n\n!start.\n\n// DECOMPOSITION: start only adopts subgoals\n+!start\n   <- !artifact_ready;\n      !banner;\n      bind(\"agent1\", \"groq\", \"openai/gpt-oss-120b\", \"\", Bid);\n      +binding(Bid);\n      !drafted(\"Write a short paragraph about photosynthesis.\");\n      !shutdown.\n\n// ACHIEVEMENT: create and focus the GL artifact\n+!artifact_ready\n   <- makeArtifact(\"gl\", \"gl.jacamo.GL\", [], GlId);\n      focus(GlId).\n\n// ACHIEVEMENT: clean exit\n+!shutdown\n   <- .stopMAS.\n\n// ACHIEVEMENT: display banner\n+!banner\n   <- see(Providers);\n      .println(\"=== Pattern 8: Iterative Refinement ===\");\n      .println(\"\");\n      .println(\"[Layer] Available providers: \", Providers).\n\n// DECOMPOSITION: draft\n+!drafted(Prompt)\n   :  binding(Bid)\n   <- call(Bid, \"draft\", \"llm.answer\", \"ANSWER\", Prompt, \"answer\", \"\", DraftRid);\n      !checked(DraftRid).\n\n// DECOMPOSITION: check\n+!checked(DraftRid)\n   :  binding(Bid)\n   <- !print_draft(DraftRid);\n      candidate(DraftRid, DraftCid);\n      !checked_candidate(DraftRid, DraftCid, Bid).\n\n+!checked_candidate(DraftRid, DraftCid, Bid)\n   :  has_candidate(DraftCid)\n   <- get(DraftCid, \"answer\", DraftText);\n      .concat(\"Review this text and suggest improvements: \", DraftText, Prompt);\n      call(Bid, \"check\", \"llm.answer\", \"ANSWER\", Prompt, \"answer\", \"\", CheckRid);\n      !revised(DraftRid, CheckRid).\n\n+!checked_candidate(DraftRid, DraftCid, Bid)\n   :  no_candidate(DraftCid)\n   <- .println(\"[AGENT] Cannot check draft - no candidate\").\n\n// ACHIEVEMENT: print draft\n+!print_draft(DraftRid)\n   <- candidate(DraftRid, DraftCid);\n      !print_draft_candidate(DraftCid).\n\n+!print_draft_candidate(DraftCid)\n   :  has_candidate(DraftCid)\n   <- get(DraftCid, \"answer\", DraftText);\n      .println(\"[Draft] \", DraftText).\n\n+!print_draft_candidate(DraftCid)\n   :  no_candidate(DraftCid)\n   <- .println(\"[Draft] no candidate\").\n\n// DECOMPOSITION: revise\n+!revised(DraftRid, CheckRid)\n   :  binding(Bid)\n   <- !print_check(CheckRid);\n      candidate(DraftRid, DraftCid);\n      candidate(CheckRid, CheckCid);\n      !revised_candidates(DraftRid, DraftCid, CheckRid, CheckCid, Bid).\n\n+!revised_candidates(DraftRid, DraftCid, CheckRid, CheckCid, Bid)\n   :  has_candidate(DraftCid) & has_candidate(CheckCid)\n   <- get(DraftCid, \"answer\", DraftText);\n      get(CheckCid, \"answer\", CheckText);\n      .concat(\"Revise this text: \", DraftText, \" Based on: \", CheckText, Prompt);\n      call(Bid, \"revise\", \"llm.answer\", \"ANSWER\", Prompt, \"answer\", \"\", FinalRid);\n      !accepted_final(FinalRid).\n\n+!revised_candidates(DraftRid, DraftCid, CheckRid, CheckCid, Bid)\n   <- .println(\"[AGENT] Cannot revise - missing candidates\").\n\n// ACHIEVEMENT: print check\n+!print_check(CheckRid)\n   <- candidate(CheckRid, CheckCid);\n      !print_check_candidate(CheckCid).\n\n+!print_check_candidate(CheckCid)\n   :  has_candidate(CheckCid)\n   <- get(CheckCid, \"answer\", CheckText);\n      .println(\"[Check] \", CheckText).\n\n+!print_check_candidate(CheckCid)\n   :  no_candidate(CheckCid)\n   <- .println(\"[Check] no candidate\").\n\n// DECOMPOSITION: accept final and print trace\n+!accepted_final(FinalRid)\n   <- !print_revised(FinalRid);\n      candidate(FinalRid, FinalCid);\n      !accept_candidate(FinalCid, FinalRid);\n      !print_trace(FinalRid);\n      !print_complete.\n\n// ACHIEVEMENT: print revised\n+!print_revised(FinalRid)\n   <- candidate(FinalRid, FinalCid);\n      !print_revised_candidate(FinalCid).\n\n+!print_revised_candidate(FinalCid)\n   :  has_candidate(FinalCid)\n   <- get(FinalCid, \"answer\", FinalText);\n      .println(\"[Revised] \", FinalText).\n\n+!print_revised_candidate(FinalCid)\n   :  no_candidate(FinalCid)\n   <- .println(\"[Revised] no candidate\").\n\n// ACHIEVEMENT: record final acceptance\n+!accept_candidate(FinalCid, FinalRid)\n   :  has_candidate(FinalCid)\n   <- accept(FinalCid, \"final refined text\", _);\n      +accepted_final(FinalRid);\n      .println(\"Final candidate - ACCEPTANCE RECORDED\").\n\n+!accept_candidate(FinalCid, FinalRid)\n   :  no_candidate(FinalCid)\n   <- .println(\"Final candidate missing - REJECTED\").\n\n// ACHIEVEMENT: print trace\n+!print_trace(Rid)\n   <- explain(Rid, Trace);\n      .println(\"\");\n      .println(\"[TRACE] \", Trace).\n\n// ACHIEVEMENT: print complete\n+!print_complete\n   <- .println(\"=== Demo Complete ===\").\n\n// RECOVERY\n-!drafted(Prompt)\n   :  not accepted_final(_)\n   <- .println(\"Pipeline FAILED\")."};
